import { useState, useRef, useEffect, useLayoutEffect, useMemo, useCallback, Component, Fragment } from "react";
import { createPortal } from "react-dom";

// ── persistent state: every worksheet keeps its inputs across close/reopen ──
function usePersist(key, initial){
  const [v,setV] = useState(()=>{ try { const s=localStorage.getItem(key); if(s!=null) return JSON.parse(s); } catch{} return typeof initial==="function"?initial():initial; });
  useEffect(()=>{ const t=setTimeout(()=>{ try { localStorage.setItem(key, JSON.stringify(v)); } catch{} }, 500); return ()=>clearTimeout(t); },[key,v]);
  return [v,setV];
}


