// Paste your keys here (Supabase dashboard → Settings → API).
// Until both are filled, the app runs on in-memory seed data (everything still works).
const SUPABASE_URL = "https://tbwmjvaewsjkxombubdo.supabase.co";
const SUPABASE_ANON_KEY = "sb_publishable_hkz4mGw22Zojdp2xekKU9A_zUmC75wo";   // publishable key — safe in the browser // anon/public key

// Lazy Supabase client. Loads @supabase/supabase-js from CDN at runtime so the
// app works both in a bundler (Vercel) and as a standalone preview.
let _sbClient = null;
let _sbTried = false;
async function getSupabase() {
  if (IS_DEMO) return null;   // demo mode never touches the live database
  if (_sbClient || _sbTried) return _sbClient;
  _sbTried = true;
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) return null; // not configured yet
  try {
    // Prefer a bundled import if available (Vercel build)
    let createClient;
    try {
      ({ createClient } = await import("@supabase/supabase-js"));
    } catch {
      // Fallback: load ESM build from CDN (works in standalone/browser preview)
      const mod = await import(/* @vite-ignore */ "https://esm.sh/@supabase/supabase-js@2");
      createClient = mod.createClient;
    }
    _sbClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      auth: {
        persistSession: true,        // survives app close, reboot, days later
        autoRefreshToken: true,      // silently renews before expiry — no surprise logouts
        detectSessionInUrl: true,    // completes magic-link / recovery redirects
        storageKey: "hh_auth",
      },
    });
    return _sbClient;
  } catch (e) {
    console.warn("Supabase unavailable, using in-memory data:", e?.message || e);
    return null;
  }
}
const supabaseConfigured = () => !IS_DEMO && !!(SUPABASE_URL && SUPABASE_ANON_KEY);

