// ─── THEME DECORATIONS (festive overlays) ─────────────────────────────────────
function ThemeDecor({decor}) {
  if(!decor) return null;
  // Minimal, calm decorations: a few corner-anchored elements with a slow gentle drift.
  // No falling streams or busy animation — present, not distracting.
  const SETS={
    flags:        [{e:"🇺🇸",p:{top:66,left:10},s:22},{e:"🇺🇸",p:{top:66,right:10},s:22,d:1.5},{e:"🎆",p:{bottom:86,right:14},s:18,d:0.7}],
    halloween:    [{e:"🎃",p:{top:66,left:10},s:22},{e:"🐈‍⬛",p:{bottom:88,right:12},s:20,d:1.2},{e:"🦇",p:{top:64,right:12},s:16,d:0.6},{e:"🕸️",p:{bottom:86,left:12},s:15,d:1.8,o:0.5}],
    thanksgiving: [{e:"🦃",p:{top:66,left:10},s:22},{e:"🍁",p:{top:64,right:12},s:18,d:1.1},{e:"🍂",p:{bottom:88,left:12},s:16,d:0.5},{e:"🌽",p:{bottom:88,right:12},s:17,d:1.6}],
    christmas:    [{e:"🎄",p:{top:66,left:10},s:22},{e:"🎅",p:{top:64,right:12},s:20,d:1.3},{e:"❄️",p:{bottom:88,left:12},s:15,d:0.6,o:0.6},{e:"🎁",p:{bottom:88,right:12},s:17,d:1.8}],
    valentines:   [{e:"💘",p:{top:66,right:12},s:22},{e:"💕",p:{top:64,left:12},s:16,d:1.2,o:0.7},{e:"💝",p:{bottom:88,left:12},s:16,d:0.5,o:0.7}],
    stpatricks:   [{e:"🎩",p:{top:66,left:10},s:22},{e:"☘️",p:{top:64,right:12},s:17,d:1.1},{e:"🪙",p:{bottom:88,right:12},s:16,d:0.6,o:0.8},{e:"🌈",p:{bottom:88,left:12},s:17,d:1.7,o:0.7}],
    easter:       [{e:"🐰",p:{top:66,left:10},s:22},{e:"🐣",p:{top:64,right:12},s:18,d:1.2},{e:"🌷",p:{bottom:88,left:12},s:16,d:0.5,o:0.8}],
    newyears:     [{e:"🎆",p:{top:60,left:"12%"},s:26,fade:true},{e:"🎇",p:{top:56,right:"12%"},s:24,fade:true,d:1.8},{e:"✨",p:{bottom:88,right:14},s:15,d:0.8,o:0.7}],
  };
  const items=SETS[decor];
  if(!items) return null;
  return (
    <div style={{position:"fixed",inset:0,zIndex:5,pointerEvents:"none",overflow:"hidden"}}>
      <style>{`
        @keyframes calmDrift{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-7px) rotate(2deg)}}
        @keyframes calmFade{0%{transform:scale(0.75);opacity:0}25%{opacity:0.55}70%{transform:scale(1.05);opacity:0.35}100%{transform:scale(1.15);opacity:0}}
      `}</style>
      {items.map((it,i)=>(
        <div key={i} style={{position:"absolute",...it.p,fontSize:it.s,opacity:it.o??0.85,animation:`${it.fade?"calmFade 6s ease-out":"calmDrift 6s ease-in-out"} ${it.d||0}s infinite`}}>{it.e}</div>
      ))}
    </div>
  );
}

// ─── TEAM TASKS — standalone to-dos assignable to anyone ──────────────────
// ─── TO-DO ──────────────────────────────────────────────────────────────────────
// Rebuilt 8/21 to Blake's My View mockup: a filled checkbox mark, "{USER} TO-DO", a
// count pill, "View all", then plain rows — circle tick, title, a grey sub-line, and
// the due date on the right — over a "+ Add New Task" footer.
//
// THE SUB-LINE IS REAL DATA. The mockup shows a category under each task ("Follow Up",
// "Conditions", "Documents") and the record has no category column — so the slot takes
// what the task actually carries: its notes if it has any, otherwise who it came from
// or who it went to. Inventing a taxonomy here would have meant new SQL and a field
// nobody fills in.
//
// TaskRow is MODULE SCOPE, not defined inside the card. It used to be a component
// created during render, which makes it a new element type every pass and remounts the
// subtree (the N3/N5 rule) — harmless while it holds no input, and wrong the moment one
// is added.
function TaskRow({t, mineRow, T, due, onToggle, onDelete}){
  return (
    <div className="lj-tkrow" style={{display:"flex",alignItems:"flex-start",gap:11,padding:"11px 0"}}>
      <button onClick={()=>onToggle(t.id)} title={t.done?"Mark not done":"Mark done"}
        style={{width:20,height:20,borderRadius:"50%",flexShrink:0,marginTop:1,cursor:"pointer",
        background:t.done?T.text2:"transparent",border:t.done?"none":`1.5px solid ${T.border}`,
        color:"#fff",fontSize:11,fontWeight:900,display:"flex",alignItems:"center",justifyContent:"center",
        padding:0}}>{t.done?"\u2713":""}</button>
      <div style={{flex:1,minWidth:0}}>
        {/* Two lines maximum, so one long task cannot own the panel. CLAMPED, not
            truncated — the full text is still in the DOM and in the title attribute,
            so nothing is lost and a screen reader reads all of it. */}
        <div title={t.title} style={{fontSize:12.5,fontWeight:800,color:T.text,letterSpacing:"-0.01em",
          lineHeight:1.35,display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",
          overflow:"hidden",textDecoration:t.done?"line-through":"none",opacity:t.done?0.55:1}}>{t.title}</div>
        <div style={{fontSize:10.5,color:T.muted,marginTop:3,overflow:"hidden",
          textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
          {t.notes ? t.notes : (mineRow?`From ${t.createdBy||"\u2014"}`:`Assigned to ${t.assignedTo}`)}
        </div>
      </div>
      {due&&<span style={{fontSize:11,fontWeight:due.late||due.today?800:600,flexShrink:0,marginTop:2,
        color:due.late?T.red:due.today?T.text2:T.muted,whiteSpace:"nowrap"}}>
        {due.late?`Overdue \u00b7 ${due.s}`:due.s}</span>}
      {/* the delete stays, at low weight — the mockup ends the row at the due date, and
          dropping this would remove the only way to clear a task you set yourself */}
      <button onClick={()=>onDelete(t.id)} title="Delete task"
        style={{background:"none",border:"none",color:T.ghost,fontSize:14,cursor:"pointer",
        padding:"2px 0 2px 8px",margin:0,flexShrink:0,opacity:0.55}}>&#215;</button>
    </div>
  );
}
// Quick Action glyphs. Module scope: JSX built inside a render is a new element
// every pass. Drawn to the same conventions as the nav icons — 24 box, stroke 1.6,
// round joins — so they read as one family rather than four imported shapes.
const QA_ICON = {
  "New Loan":     <><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v4h4"/><path d="M12 11v6M9 14h6"/></>,
  "Pre-Approval": <><circle cx="12" cy="8.5" r="3.6"/><path d="M5 20c1.4-3.9 4-5.6 7-5.6s5.6 1.7 7 5.6"/></>,
  "Offer Sheet":  <><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v4h4"/><path d="M9 12h6M9 16h4"/></>,
  "Income Sheet": <><rect x="4.5" y="3" width="15" height="18" rx="2"/><path d="M8 8h8M8 12h3M8 16h3M15 12v4"/></>,
};
function TeamTasksCard({tasks,currentUser,T,HL,onAdd,onToggle,onDelete,previewMode=false}) {
  const [adding,setAdding]=useState(false);
  const [showWaiting,setShowWaiting]=useState(false);
  const [title,setTitle]=useState(""); const [who,setWho]=useState(currentUser||"Blake");
  const [due,setDue]=useState(""); const [note,setNote]=useState("");
  const mine=tasks.filter(t=>t.assignedTo===currentUser&&!t.done).sort((a,b)=>{ const ao=a.createdBy&&a.createdBy!==currentUser?0:1; const bo=b.createdBy&&b.createdBy!==currentUser?0:1; if(ao!==bo) return ao-bo; return (a.dueDate||"9999").localeCompare(b.dueDate||"9999"); });
  const byMe=tasks.filter(t=>t.createdBy===currentUser&&t.assignedTo!==currentUser&&!t.done);
  const submit=()=>{ if(!title.trim()) return; onAdd({title:title.trim(),assignedTo:who,dueDate:due,notes:note.trim()}); setTitle("");setDue("");setNote("");setAdding(false); };
  // The mockup labels the next two days in words and everything else by date, which is
  // how Blake reads them. A date-only string is pinned to local noon so it cannot land
  // on the previous day in Eastern (the P4/P5 timezone fix).
  const fmtDue=d=>{ if(!d) return null; const dt=new Date(d+"T12:00"); if(isNaN(dt.getTime())) return null;
    const today=new Date(); today.setHours(12,0,0,0);
    const diff=Math.round((dt-today)/86400000);
    const s = diff===0 ? "Today" : diff===1 ? "Tomorrow"
      : dt.toLocaleDateString("en-US",{month:"short",day:"numeric"});
    return {s, late:diff<0, today:diff===0}; };
  // `preview` shows the first three and a "View all N" — the My View rail wants a
  // useful glance, not a 520px scroller. Opt-in, so the Dashboard card is unchanged.
  const [previewOff,setPreviewOff] = useState(false);
  const preview = previewMode && !previewOff;
  const [cardOpen,setCardOpen]=useState(()=>{try{const v=localStorage.getItem(`todoCardOpen_${currentUser}`); if(v!==null) return v==="1";}catch{} return true;});
  useEffect(()=>{try{localStorage.setItem(`todoCardOpen_${currentUser}`,cardOpen?"1":"0");}catch{}},[cardOpen,currentUser]);
  const inp={width:"100%",boxSizing:"border-box",background:T.card,border:`1px solid ${T.inputBorder}`,borderRadius:8,padding:"8px 10px",color:T.text,fontSize:12,outline:"none"};
  return (
    <>
      {/* The count sits IN the title and the header itself is the toggle — no separate
          badge and no "Hide" link. aria-expanded so the control still says what it does
          to a screen reader now that the visible word is gone. */}
      <MvHead icon="check" T={T}
        onClick={()=>setCardOpen(v=>!v)} expanded={cardOpen}
        title={<>{currentUser} To-Do{mine.length>0?` (${mine.length})`:""}</>}/>
      {cardOpen&&<div style={{padding:"0 15px 4px",maxHeight:preview?"none":520,overflowY:preview?"visible":"auto",overscrollBehavior:"contain",
        ["--lj-tkrule"]:cardEdge(T)}}>
      {adding&&(
        <div style={{background:T.inner,borderRadius:10,padding:"11px 12px",display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
          <input value={title} onChange={e=>setTitle(e.target.value)} placeholder="What needs done? e.g. Schedule the Smith closing" style={inp}/>
          <div style={{display:"flex",gap:8}}>
            <div style={{flex:1}}>
              <div style={{fontSize:9.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Assign To</div>
              <select value={who} onChange={e=>setWho(e.target.value)} style={{...inp,padding:"8px 8px"}}>
                {TEAM.map(n=><option key={n} value={n}>{n}</option>)}
              </select>
            </div>
            <div style={{flex:1}}>
              <div style={{fontSize:9.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Due (optional)</div>
              <input type="date" value={due} onChange={e=>setDue(e.target.value)} style={{...inp,colorScheme:"light"}}/>
            </div>
          </div>
          <input value={note} onChange={e=>setNote(e.target.value)} placeholder="Notes (optional)" style={inp}/>
          <button onClick={submit} style={{background:T.header,border:"none",borderRadius:8,padding:"9px 0",color:"#fff",fontWeight:800,fontSize:12,cursor:"pointer"}}>Assign to {who}</button>
        </div>
      )}
      {(preview ? mine.slice(0,3) : mine).map(t=><TaskRow key={t.id} t={t} mineRow T={T} due={fmtDue(t.dueDate)} onToggle={onToggle} onDelete={onDelete}/>)}
      {preview && mine.length>3 && (
        <div onClick={()=>setPreviewOff(true)} title="Show every task"
          style={{padding:"9px 2px 4px",fontSize:11.5,fontWeight:700,color:T.text2,cursor:"pointer"}}>
          View all {mine.length}</div>)}
      {byMe.length>0&&<>
        <button onClick={()=>setShowWaiting(v=>!v)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",width:"100%",background:"transparent",border:"none",cursor:"pointer",padding:"10px 0 2px",borderTop:mine.length?`1px solid ${T.border}`:"none"}}>
          <span className="lj-trow" style={{fontSize:9.5,color:T.muted,fontWeight:800,letterSpacing:"0.09em",textTransform:"uppercase"}}>Waiting on others ({byMe.length})</span>
          <span style={{fontSize:10,color:T.ghost,transform:showWaiting?"rotate(90deg)":"none",transition:"transform 0.15s"}}>&#8250;</span>
        </button>
        {showWaiting&&byMe.map(t=><TaskRow key={t.id} t={t} mineRow={false} T={T} due={fmtDue(t.dueDate)} onToggle={onToggle} onDelete={onDelete}/>)}
      </>}
      {!adding&&mine.length===0&&byMe.length===0&&<div style={{fontSize:11.5,color:T.ghost,fontStyle:"italic",padding:"10px 0 4px"}}>Nothing assigned &mdash; tap Add New Task to send someone a to-do.</div>}
      </div>}
      {/* the mockup's footer, and the only way into the assign form now that the header
          carries the count instead of a button */}
      {cardOpen&&(
        <button onClick={()=>setAdding(a=>!a)} className="lj-row"
          style={{display:"flex",alignItems:"center",justifyContent:"center",gap:8,width:"100%",
          background:"transparent",border:"none",borderTop:`1px solid ${T.border}`,
          padding:"13px 15px",cursor:"pointer",color:T.text2,fontSize:11.5,fontWeight:800}}>
          <MvIco name="plus" size={14} color={T.text2}/>{adding?"Cancel":"Add New Task"}
        </button>
      )}
    </>
  );
}

// ─── CLOSINGS · NEXT 7 DAYS — rolling window from today, tap a loan for where & when ───
function ClosingThisWeek({leads,loans,T,HL,onSaveDetails,onFund,onDismiss,onUnfund}) {
  const [openId,setOpenId]=useState(null);
  const [dTime,setDTime]=useState(""); const [dLoc,setDLoc]=useState(""); const [dNotes,setDNotes]=useState(""); const [dDate,setDDate]=useState("");
  // Rolling window: today through six days out, recomputed on every render and
  // re-checked on a timer so a session left open overnight rolls to the new day.
  const [tick,setTick]=useState(0);
  useEffect(()=>{ const iv=setInterval(()=>setTick(t=>t+1), 10*60*1000);
    const onVis=()=>{ if(document.visibilityState==="visible") setTick(t=>t+1); };
    document.addEventListener("visibilitychange",onVis);
    return ()=>{ clearInterval(iv); document.removeEventListener("visibilitychange",onVis); };
  },[]);
  const today=new Date(); today.setHours(0,0,0,0);
  const mon=today;
  const fri=new Date(today); fri.setDate(today.getDate()+6);
  const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  const a=iso(mon), b=iso(fri), todayIso=iso(today);
  const seen=new Set();
  const events=[
    ...leads.filter(l=>l.closingDate&&!["ghosted","archived","creditrepair","onhold"].includes(l.stage)),
    ...loans.filter(l=>l.closingDate&&l.stage==="closed"&&!l._fromLead&&!l.closingDismissed),
  ].filter(l=>{ if(l.closingDate<a||l.closingDate>b||seen.has(l.id)) return false; seen.add(l.id); return true; })
   .sort((x,y)=>{ const d=x.closingDate.localeCompare(y.closingDate); if(d) return d;
     const t=s=>{ const m=/(\d{1,2}):?(\d{2})?\s*(a|p)/i.exec(s||""); if(!m) return 9999; let h=parseInt(m[1])%12; if(/p/i.test(m[3])) h+=12; return h*60+(parseInt(m[2])||0); };
     return t(x.closingTime)-t(y.closingTime); });
  const fmtK=v=>v>=1000000?`$${(v/1000000).toFixed(1)}M`:v>0?`$${Math.round(v/1000)}K`:"TBD";
  const vol=events.reduce((s2,l)=>s2+(l.loanAmount||l.amount||0),0);
  const rng=`${mon.toLocaleDateString("en-US",{month:"short",day:"numeric"})} – ${fri.toLocaleDateString("en-US",{month:"short",day:"numeric"})}`;   // eslint-disable-line no-unused-vars
  const open=l=>{ if(openId===l.id){setOpenId(null);return;} setOpenId(l.id); setDDate(l.closingDate||""); setDTime(l.closingTime||""); setDLoc(l.closingLocation||""); setDNotes(l.closingNotes||""); };
  const save=l=>{ onSaveDetails(l,{date:dDate,time:dTime,location:dLoc,notes:dNotes}); setOpenId(null); };
  const inp={width:"100%",boxSizing:"border-box",background:T.card,border:`1px solid ${T.inputBorder}`,borderRadius:8,padding:"7px 10px",color:T.text,fontSize:12,outline:"none"};
  return (
    <div style={{margin:"0 16px 14px",borderRadius:12,overflow:"hidden",border:`1px solid ${T.border}`,background:T.card}}>
      <div className="lj-cmdhdr" style={{padding:"9px 16px",borderBottom:`1px solid ${T.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div style={{fontSize:9.5,fontWeight:900,color:T.text2,letterSpacing:"0.09em",textTransform:"uppercase"}}>Closings – Next 7 Days</div>
        <div style={{fontSize:10,color:T.muted,fontWeight:600}}>{rng}{events.length>0?` • ${events.length} unit${events.length!==1?"s":""} • ${fmtK(vol)}`:""}</div>
      </div>
      {events.length===0&&<div style={{padding:"9px 16px",fontSize:12,color:T.ghost,fontWeight:600}}>No closings scheduled in the next 7 days.</div>}
      {events.map((l,i)=>{
        const isToday=l.closingDate===todayIso;
        const isFunded=l.stage==="closed";
        const _d = new Date(l.closingDate+"T12:00");
        const dn = _d.toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric"});
        const dowS = _d.toLocaleDateString("en-US",{weekday:"short"}).toUpperCase();
        const monS = _d.toLocaleDateString("en-US",{month:"short"}).toUpperCase();
        const dayN = _d.getDate();
        const amt=l.loanAmount||l.amount||0;
        const expanded=openId===l.id;
        return (
          <div key={l.id} style={{
            // separators are gone: the tinted blocks and the gap between them do that
            // job, and a rule ON TOP of a tint reads as a nested card, which is exactly
            // what Blake asked this NOT to become.
            marginBottom:i<events.length-1?6:0,
            // Blake 8/19: no wash and no edge for a funded row — the black chip and the
            // check already carry that state, matching the dashboard month columns.
            background:!isFunded&&isToday?`${HL.border}0d`:"transparent",borderLeft:"3px solid transparent"}}>
            <div onClick={()=>open(l)} style={{padding:"8px 12px",margin:"0 12px",
              background:T.inner,borderRadius:8,
              display:"flex",justifyContent:"space-between",alignItems:"center",cursor:"pointer",gap:10}}>
              {isFunded
                ? <span onClick={e=>{e.stopPropagation();
                    if(onUnfund && window.confirm(`${l.name||l.borrower} is marked FUNDED.\n\nOK = move it back to the pipeline.\nCancel = leave it funded and just clear it from this list.`)) onUnfund(l);
                    else onDismiss&&onDismiss(l);
                  }} title="Funded — tap to move it back, or to clear it from this list" style={{width:22,height:22,borderRadius:6,flexShrink:0,background:fundedChipBg(T.card),color:fundedChipInk(T.card),fontSize:12,fontWeight:900,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",border:`2px solid ${fundedChipBg(T.card)}`}}>✓</span>
                : onFund&&<span onClick={e=>{e.stopPropagation();if(window.confirm(`Mark ${l.name||l.borrower} as Closed & Funded? Moves to the Funded database.`)) onFund(l);}} title="Tap when closed & funded" style={{width:22,height:22,borderRadius:11,flexShrink:0,border:`2px solid ${T.text2}`,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}/>}
              {/* WHEN, as its own column. It was buried mid-sentence in a 9.5px muted
                  run, so the dates could not be scanned down the card. */}
              <div style={{flexShrink:0,width:58,textAlign:"center",paddingRight:4}}>
                <div style={{fontSize:9.5,fontWeight:700,color:T.muted,letterSpacing:"0.07em"}}>{dowS}</div>
                <div style={{fontSize:19,fontWeight:800,color:T.text,lineHeight:1.02,
                  fontVariantNumeric:"tabular-nums"}}>{dayN}</div>
                <div style={{fontSize:9.5,fontWeight:600,color:T.muted,letterSpacing:"0.07em"}}>{monS}</div>
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontSize:11.5,fontWeight:800,color:T.text,display:"flex",alignItems:"center",gap:7,minWidth:0}}>
                  <span style={{minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                    {l.name||l.borrower}<ContBadge on={l.homeSaleContingency} T={T} size="sm"/></span>
                  {isFunded&&<span style={{fontSize:9.5,fontWeight:900,color:fundedChipInk(T.card),background:fundedChipBg(T.card),borderRadius:4,padding:"2px 6px",letterSpacing:"0.05em"}}>FUNDED · ✓ to undo</span>}
                  {!isFunded&&isToday&&<span style={{fontSize:9.5,fontWeight:900,color:"#fff",background:HL.border,borderRadius:4,padding:"2px 6px",letterSpacing:"0.05em"}}>TODAY</span>}
                </div>
                <div style={{fontSize:11.5,color:T.muted,marginTop:3,fontWeight:500,display:"flex",alignItems:"center",gap:5,minWidth:0,whiteSpace:"nowrap"}}>
                  <span style={{flexShrink:0}}>{l.closingTime?`${l.closingTime} • `:""}{`${fmtLoanType(l.loanType)}`}</span>
                  {l.closingLocation&&(<span style={{color:T.text2,fontWeight:600,minWidth:0,overflow:"hidden",textOverflow:"ellipsis"}} title={l.closingLocation}>• {l.closingLocation}</span>)}
                </div>
              </div>
              <div style={{display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
                <div style={{fontSize:11.5,fontWeight:800,color:T.text,fontVariantNumeric:"tabular-nums"}}>{fmtK(amt)}</div>
                <div style={{fontSize:13,color:T.ghost,transform:expanded?"rotate(90deg)":"none",transition:"transform 0.15s"}}>›</div>
              </div>
            </div>
            {expanded&&(
              <div style={{padding:"0 16px 13px",display:"flex",flexDirection:"column",gap:7}}>
                <div style={{display:"flex",gap:7}}>
                  <div style={{flex:1.2}}><div style={{fontSize:9.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Closing Date</div><input type="date" value={dDate} onChange={e=>setDDate(e.target.value)} style={{...inp,padding:"6px 8px"}}/></div>
                  <div style={{flex:1}}><div style={{fontSize:9.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Time</div><input value={dTime} onChange={e=>setDTime(e.target.value)} placeholder="10:00 AM" style={inp}/></div>
                  <div style={{flex:2}}><div style={{fontSize:9.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Where</div><input value={dLoc} onChange={e=>setDLoc(e.target.value)} placeholder="Title company / attorney office" style={inp}/></div>
                </div>
                <div><div style={{fontSize:9.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Notes</div><input value={dNotes} onChange={e=>setDNotes(e.target.value)} placeholder="Cashier's check amount, gate code…" style={inp}/></div>
                <button onClick={()=>save(l)} style={{background:T.navy,border:"none",borderRadius:8,padding:"8px 0",color:"#fff",fontWeight:800,fontSize:11,cursor:"pointer"}}>Save Closing Details</button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// PMS 286 blue stage palette
const STAGE_PALETTE = {
  clay:"#5d626a", amber:"#0033A0", sage:"#3a5fc0", forest:"#0033A0",
  moss:"#1a47b0", bark:"#454a52", terracotta:"#c0504d", olive:"#4d7fd6",
  pine:"#00237a", wheat:"#3a5fc0", stone:"#787e88", rust:"#9a5a3c",
};

// ─── CONSTANTS ────────────────────────────────────────────────────────────────
// ── TITLE COMPANY FEE PRESETS ──
// Blake: send per-company costs and they go here. Blank "" = leave that field untouched.
// Keys: closing (Closing Fee), cpl (Protection Ltr), courier, endorse (Endorsements), exam, ltitle (Lender's Title — blank keeps auto)
const KY_CITY_COUNTY = { "harrodsburg":"Mercer","burgin":"Mercer","danville":"Boyle","perryville":"Boyle","junction city":"Boyle","stanford":"Lincoln","crab orchard":"Lincoln","hustonville":"Lincoln","waynesburg":"Lincoln","lancaster":"Garrard","paint lick":"Garrard","lexington":"Fayette","nicholasville":"Jessamine","wilmore":"Jessamine","richmond":"Madison","berea":"Madison","somerset":"Pulaski","liberty":"Casey","lebanon":"Marion","springfield":"Washington","versailles":"Woodford","georgetown":"Scott","frankfort":"Franklin","winchester":"Clark","harrodsburg ":"Mercer","salvisa":"Mercer","louisville":"Jefferson" };
const KY_PVA_URL = (county) => {
  const c = String(county||"").toLowerCase();
  if (c==="fayette") return "https://fayettepva.com";
  if (c==="jefferson") return "https://jeffersonpva.ky.gov";
  return c ? `https://www.qpublic.net/ky/${c}/` : "https://www.qpublic.net/ky/";
};
const detectKyCounty = (address) => {
  const a = String(address||"").toLowerCase();
  for (const city of Object.keys(KY_CITY_COUNTY)) if (a.includes(city)) return KY_CITY_COUNTY[city];
  return "";
};
// Fixed fees pulled from actual closing disclosures (Aug 2025 - Jul 2026). These DO vary
// by company — closing fee, exam, courier, endorsements, wire, deed prep.
//
// The LENDER'S TITLE PREMIUM does not. It is a filed rate in Kentucky, so the same loan
// costs the same policy premium wherever it is written. Earlier builds carried a separate
// ltitleRate per company, derived from individual CDs — but those files had different loan
// sizes, so what looked like company variation was really loan-size variation. It priced
// the identical policy anywhere from $763 to $1,090 on a $250k loan.
// One rate now, overridable in Settings so Blake can set the real filed figure.
const LENDER_TITLE_RATE_DEFAULT = 0.0037;
const TITLE_FEE_PRESETS = {
  "The Land Group":         { closing:"595", cpl:"50", courier:"45", endorse:"", exam:"100",  muniPct:0.06, note:"Somerset city premium tax applies · $10 filing fee" },
  "Bluegrass Land Title":   { closing:"250", cpl:"50", courier:"", endorse:"", exam:"",  muniPct:0.09, settle:"650", deedPrep:"250",
                              note:"Closing $250 + settlement $650 · Frankfort city premium tax applies" },
  "Five Star Land Title":   { closing:"475", cpl:"50", courier:"35", endorse:"", exam:"400",  wire:"25", signing:"75", recording:"35",
                              note:"Closing $475 \u00b7 doc signing $75 \u00b7 wire $25 \u00b7 recording svc $35 \u00b7 policy via Westcor" },
  "Kentucky Abstract Title":{ closing:"400", cpl:"50", courier:"60", endorse:"50", exam:"400",  note:"Deed prep billed separately by attorney (~$150)" },
  "T.E.C.E. Title Services":{ closing:"200", cpl:"50", courier:"75", endorse:"50", exam:"450",  wire:"60", deedPrep:"100",
                              note:"Commitment fee $450 · endorsements $50 each · wire in/out $30 each" },
};
// Lender's title premium scales with the loan and is the SAME at every title company.
// rateOverride comes from Settings when Blake has the filed figure to hand.
const titlePremium = (company, loanAmount, rateOverride) => {
  const amt = Number(loanAmount)||0;
  const rate = Number(rateOverride) > 0 ? Number(rateOverride) : LENDER_TITLE_RATE_DEFAULT;
  if(amt > 0) return Math.round(amt * rate);
  const p = TITLE_FEE_PRESETS[company];
  return p && p.ltitle ? Number(p.ltitle) : null;
};
// Session passcodes. See the note by PASS_GATE below on what these do and do not do.
const PASSCODES = { Blake:"5832", Donna:"0222", Tamara:"2272" };
const BOSS         = IS_DEMO ? "Branch Manager" : "Blake";                            // who sees triage, P&L, portal tools
const TEAM         = IS_DEMO ? DEMO_TEAM : ["Blake","Donna","Tamara","Processor"];
// Auth accounts map to the names the CRM already uses everywhere.
const TEAM_EMAILS = {
  "blake.henderson@naf.com":"Blake",
  "donna.henderson@naf.com":"Donna",
  "tamara.marsh@naf.com":"Tamara",
};
const nameForEmail = (email) => TEAM_EMAILS[String(email||"").trim().toLowerCase()] || "";

// Program buckets for counting. Labels drift over the years ("Rural Development", "RD",
// "FHA/USDA"), so every record is normalized here — FHA and USDA stay distinct, and any
// unrecognized label lands in Other rather than vanishing from the totals.
// Home-sale contingency marker — deliberately loud, since it changes how a file is worked.
function ContBadge({on, T, size}){
  if(!on) return null;
  const sm = size==="sm", xs = size==="xs";
  return <span title="Home sale contingency — buyer must sell their current home" style={{display:"inline-block",background:"rgba(138,28,28,0.10)",border:"1px solid #8a1c1c",color:"#8a1c1c",borderRadius:4,padding:xs?"0 2.5px":sm?"0 3px":"0 4px",fontSize:xs?7:sm?8.5:9.5,fontWeight:900,letterSpacing:"0.02em",marginLeft:xs?0:5,verticalAlign:"baseline",lineHeight:1.4,opacity:xs?0.85:1}}>C</span>;
}
// WaiverBadge was REMOVED 8/24: the chip is off the summary cards and the full
// "APPRAISAL WAIVER" plate inside the file replaced it. Deleted rather than left
// unused, because an orphaned component is how a removed badge comes back.
// ─── PAGE HEADER ────────────────────────────────────────────────────────────────
// One block, two pages. The Dashboard and My View print the same title / sub-line /
// date / action row, so it is written ONCE here instead of copied — two definitions
// of one header is exactly the drift this file keeps punishing. The BUTTON LIST is
// built once at component scope and passed in as `acts`, so neither page can end up
// with a different row of icons than the other.
function PageHead({title, sub, T, SCHEME, acts, isDarkMode, onToggleMode, onSearch}){
  return (
    <div className="dg-full dg-i-head lj-pagehead" style={{padding:"14px 20px 16px",display:"flex",
      justifyContent:"space-between",alignItems:"flex-start",background:"transparent",marginBottom:0}}>
      <div style={{minWidth:0}}>
        <div style={{fontSize:20.5,fontWeight:700,color:T.text,letterSpacing:"-0.02em",lineHeight:1.18}}>{title}</div>
        <div style={{fontSize:11,color:T.muted,fontWeight:500,minWidth:0,marginTop:3,
          overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}} className="lj-hdrsub">{sub}</div>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        {/* Blake 9/16 — search moves from an icon into a real field on the dashboard.
            It opens the SAME global search that already existed; nothing new behind it. */}
        {onSearch && (
          <div className="lj-headsearch" onClick={onSearch}
            style={{display:"none",alignItems:"center",gap:8,minWidth:300,cursor:"pointer",
              background:T.card,border:`1px solid ${T.border}`,borderRadius:10,padding:"8px 12px"}}>
            <svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke={T.muted}
              strokeWidth="1.8" strokeLinecap="round" style={{flexShrink:0}}>
              <circle cx="9" cy="9" r="6"/><path d="M13.5 13.5 17 17"/></svg>
            <span style={{fontSize:12.5,color:T.ghost,fontWeight:500}}>Search loans, clients, or partners…</span>
          </div>
        )}
        <div style={{fontSize:11,color:T.muted,fontWeight:600,letterSpacing:"0.01em",whiteSpace:"nowrap",marginRight:4}}>
          {new Date().toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"})}</div>
        {onToggleMode && (
          <button onClick={onToggleMode} title={isDarkMode?"Switch to light":"Switch to dark"}
            aria-label={isDarkMode?"Switch to light mode":"Switch to dark mode"}
            aria-pressed={isDarkMode?"true":"false"}
            style={{width:28,height:28,borderRadius:"50%",background:"transparent",
              border:`1px solid ${T.border}`,color:T.muted,display:"flex",alignItems:"center",
              justifyContent:"center",cursor:"pointer",padding:0,flexShrink:0}}>
            <svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor"
              strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" style={{display:"block"}}>
              {isDarkMode
                ? <path d="M15.5 11.4A6 6 0 0 1 8.6 4.5a6 6 0 1 0 6.9 6.9Z"/>
                : <><circle cx="10" cy="10" r="3.4"/><path d="M10 2.4v1.7M10 15.9v1.7M17.6 10h-1.7M4.1 10H2.4M15.4 4.6l-1.2 1.2M5.8 14.2l-1.2 1.2M15.4 15.4l-1.2-1.2M5.8 5.8 4.6 4.6"/></>}
            </svg>
          </button>
        )}
        {/* `.lj-pageactions` is hidden inline and switched on inside the desktop media
            query — the row already existed before this component; it was moved here,
            not duplicated. */}
        <div className="lj-pageactions" style={{display:"none",alignItems:"center",gap:14}}>
          {(acts||[]).map(b=>(
            <button key={b.k} onClick={b.on} title={b.t} aria-label={b.t}
              style={{width:40,height:40,borderRadius:"50%",
                background:b.ai?rgbaOf(SCHEME.accent,0.13):T.card,
                border:`1px solid ${b.ai?rgbaOf(SCHEME.accent,0.22):T.border}`,
                color:b.ink||T.text2,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",
                padding:0,flexShrink:0,boxShadow:b.ai?"none":"0 1px 2px rgba(16,24,40,.05)",position:"relative"}}>
              {b.ai
                ? <span style={{fontSize:14,fontWeight:900,letterSpacing:"-0.01em",color:inkSafe(SCHEME.accent,T.card,4.5)}}>AI</span>
                : <svg width="22" height="22" viewBox="0 0 20 20" style={{display:"block"}}>{b.d}</svg>}
              {/* The badge belonged to the bell, which was removed on 8/23. Nothing in
                  pageActs sets `badge` now, so the render is gone rather than left as
                  dead code — an unused branch is how a removed control comes back. */}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
// ─── MY VIEW CARD FURNITURE ─────────────────────────────────────────────────────
// Blake's 8/21 mockup gives all four My View cards ONE header treatment: a small
// solid accent glyph, an uppercase accent title, and an optional right-hand slot.
// Written once here so the four cards cannot drift apart the way the dashboard's
// three attention cards did before X89.
//
// COLOUR: the mockup is blue throughout, but nothing here is pinned to a hex — the
// glyph and title take T.text2, the ink the card headers, the goal ring and the
// month labels already wear, so a chip matches the rest of the theme by
// construction (the X93 rule). On the sixteen schemes that ship a dark palette
// under the "light" key, text2 is already the readable ink.
function MvIco({name, size=15, color=""}){
  const s = size;
  const P = {
    // solid star — priority
    star:  <path d="M10 1.6l2.6 5.3 5.8.85-4.2 4.1 1 5.8L10 14.9l-5.2 2.75 1-5.8L1.6 7.75l5.8-.85L10 1.6Z"/>,
    // solid bolt — activity
    bolt:  <path d="M11.6 1.5L4 11.2h4.2l-.6 7.3L16 8.5h-4.5l.1-7Z"/>,
    // outline folder — work queues
    folder:<path d="M2.6 5.4c0-.8.6-1.4 1.4-1.4h3l1.6 1.9h6.4c.8 0 1.4.6 1.4 1.4v7.3c0 .8-.6 1.4-1.4 1.4H4c-.8 0-1.4-.6-1.4-1.4V5.4Z"
             fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round"/>,
    // filled rounded checkbox with a knocked-out tick — to-do
    check: <><rect x="2" y="2" width="16" height="16" rx="4"/><path d="M6 10.2l2.7 2.7L14.2 7.4"
             fill="none" stroke="#fff" strokeWidth="2.1" strokeLinecap="round" strokeLinejoin="round"/></>,
    // outline person — the realtor cell in the file table
    user:  <><circle cx="10" cy="7" r="3.1" fill="none" stroke="currentColor" strokeWidth="1.5"/>
             <path d="M4.4 16.4c.6-2.9 2.9-4.5 5.6-4.5s5 1.6 5.6 4.5" fill="none" stroke="currentColor"
             strokeWidth="1.5" strokeLinecap="round"/></>,
    // chevron — row affordance and the "View all" caret
    chev:  <path d="M8 4.6L13.2 10 8 15.4" fill="none" stroke="currentColor" strokeWidth="1.9"
             strokeLinecap="round" strokeLinejoin="round"/>,
    plus:  <path d="M10 4.4v11.2M4.4 10h11.2" fill="none" stroke="currentColor" strokeWidth="2"
             strokeLinecap="round"/>,
    // ── Clients page (8/23 spec) ──
    funnel:<path d="M2.8 3.6h14.4l-5.6 6.6v5.4l-3.2 1.8v-7.2L2.8 3.6Z" fill="none"
             stroke="currentColor" strokeWidth="2" strokeLinejoin="round"/>,
    users: <><circle cx="7.6" cy="7" r="2.9" fill="none" stroke="currentColor" strokeWidth="2"/>
             <path d="M2.4 16.4c.5-2.7 2.6-4.2 5.2-4.2s4.7 1.5 5.2 4.2" fill="none"
             stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
             <path d="M13.4 4.6a2.9 2.9 0 0 1 0 4.9M14.6 12.6c1.6.5 2.7 1.8 3 3.8" fill="none"
             stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></>,
    chart: <path d="M3.6 16.4V9.2M8.6 16.4V3.6M13.6 16.4v-5" fill="none" stroke="currentColor"
             strokeWidth="2" strokeLinecap="round"/>,
    flag:  <path d="M4.4 17V3.4M4.4 4.2h9.8l-1.7 3.2 1.7 3.2H4.4" fill="none"
             stroke="currentColor" strokeWidth="2" strokeLinejoin="round" strokeLinecap="round"/>,
    cal:   <><rect x="3" y="4.6" width="14" height="12.2" rx="2" fill="none" stroke="currentColor"
             strokeWidth="1.8"/><path d="M3 8.4h14M6.8 2.8v3.2M13.2 2.8v3.2" fill="none"
             stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></>,
    // solid document / upload — the two real application events
    doc:   <><path d="M5.4 3.2h5.3l4 4v9.6c0 .6-.5 1-1 1H5.4c-.6 0-1-.4-1-1V4.2c0-.6.4-1 1-1Z"/>
             <path d="M6.9 9.4h6.2M6.9 12h6.2M6.9 14.6h4" stroke="#fff" strokeWidth="1.2" strokeLinecap="round"/></>,
    up:    <><circle cx="10" cy="10" r="8"/><path d="M10 14.2V6.6M6.7 9.7L10 6.3l3.3 3.4M6.6 15.6h6.8"
             fill="none" stroke="#fff" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></>,
  };
  return <svg width={s} height={s} viewBox="0 0 20 20" aria-hidden="true"
    style={{display:"block",flexShrink:0,color:color||"currentColor",fill:color||"currentColor"}}>{P[name]||null}</svg>;
}
// The right-hand "View all >" affordance. It is only ever rendered by a card that has
