function loanBucket(t){
  const x = String(t||"").trim();
  // Blank (older records) and the explicit TBD (new ones) mean the same thing: nobody
  // has chosen yet. They MUST share a bucket or the chart double-counts the same state
  // under two labels — "" fell to Unlabeled while "TBD" fell through to Other.
  if(!x || x.toUpperCase()===LOAN_TYPE_TBD) return LOAN_TYPE_TBD;
  const u = x.toUpperCase();
  if(/FHA\s*\/\s*USDA|USDA\s*\/\s*FHA/.test(u)) return "FHA/USDA (needs split)";
  const khc    = /\bKHC\b|KENTUCKY HOUSING/.test(u);
  const isUSDA = /USDA|RURAL DEV|\bRD\b|GUARANTEED RURAL/.test(u);
  const isFHA  = /\bFHA\b/.test(u);
  const isVA   = /\bVA\b|VETERAN/.test(u);
  if(khc){
    if(isUSDA) return "KHC USDA";
    if(isFHA)  return "KHC FHA";
    if(isVA)   return "KHC VA";
    return "KHC CONV";
  }
  if(isUSDA) return "USDA";
  if(isFHA)  return "FHA";
  if(isVA)   return "VA";
  if(/JUMBO/.test(u)) return "Jumbo";
  if(/NON.?QM/.test(u)) return "Non-QM";
  if(/CONV|FANNIE|FREDDIE/.test(u)) return "Conventional";
  return "Other";
}
// "Unlabeled" is replaced by "TBD" — the same state, named the way Blake asked for it,
// and sitting LAST so an unchosen file never leads the chart.
const BUCKET_ORDER = ["Conventional","FHA","USDA","VA","KHC FHA","KHC USDA","KHC VA","KHC CONV","Jumbo","Non-QM","FHA/USDA (needs split)","Other","TBD"];
// TBD LEADS THE LIST so it is a real, selectable value rather than a blank the
// dropdown cannot show. A record that says TBD and a dropdown that has no such option
// would render as the first item — i.e. silently look like "Conventional" again.
const LOAN_TYPE_TBD = "TBD";
const LOAN_TYPES   = [LOAN_TYPE_TBD,"Conventional","FHA","USDA","VA","KHC FHA","KHC VA","KHC CONV","KHC USDA","Non-QM","Jumbo"];
// An unset or blank type reads as TBD everywhere, so older records written before this
// change (which carry "") say the same thing as new ones without a data migration.
const fmtLoanType = v => { const s = String(v||"").trim(); return s || LOAN_TYPE_TBD; };
const LOAN_PURPOSE = ["Purchase","Refinance"];
const PARTNER_TYPES= ["Realtor","Financial Advisor","CPA","Builder","Attorney","Insurance","Other"];
const TEAM_COLORS  = IS_DEMO ? { "Branch Manager":"#0033A0", "Carla (LP1)":"#787e88", "Devin (LP2)":"#0a6b34", "Sonia (LP3)":"#8a5a1e" } : { Blake:"#0033A0", Tamara:"#787e88", Donna:"#0033A0", Processor:"#0a6b34" };
const tierColor    = { Elite:"#e8a0c0", Diamond:"#60d4f4", Platinum:"#7f96ad" };
const BUILD_TAG = "b0725-X322";

// Holiday schemes are archived out of the picker and chosen by MONTH instead of by date,
// so nothing needs to know when Easter falls. Returns "" for months with no holiday.
const HOLIDAY_BY_MONTH = {1:"newyears",2:"valentines",3:"stpatricks",4:"easter",
                          7:"july4th",10:"halloween",11:"thanksgiving",12:"christmas"};
function holidayScheme(d){
  const key = HOLIDAY_BY_MONTH[(d||new Date()).getMonth()+1] || "";
  return (key && COLOR_SCHEMES[key]) ? key : "";
}
function LoginScreen({T, onDone}) {
  const [email,setEmail] = useState("");
  const [pw,setPw] = useState("");
  const [busy,setBusy] = useState(false);
  const [err,setErr] = useState("");
  const go = async () => {
    if (!email || !pw) { setErr("Email and password required"); return; }
    setBusy(true); setErr("");
    try { await authSignIn(email, pw); onDone && onDone(); }
    catch(e){ setErr(String(e?.message||e).replace(/^AuthApiError:\s*/,"")); }
    setBusy(false);
  };
  const W = {width:"100%",boxSizing:"border-box",background:T.card,border:`1px solid ${T.inputBorder}`,borderRadius:10,padding:"11px 13px",color:T.text,fontSize:14,outline:"none",marginBottom:9};
  return (
    <div style={{minHeight:"100vh",background:T.page,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",fontFamily:"-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif",padding:24}}>
      <div style={{fontSize:20,fontWeight:900,color:T.text,fontFamily:"Georgia,'Times New Roman',serif",letterSpacing:"0.02em",textShadow:"0 0 26px rgba(201,162,39,0.22), 0 0 70px rgba(201,162,39,0.08)"}}>HENDERSON TEAM</div>
      <div style={{fontSize:9.5,color:T.text2,fontWeight:800,letterSpacing:"0.09em",textTransform:"uppercase",marginTop:6,marginBottom:22}}>Reputation · Service · Results</div>
      <div style={{width:"100%",maxWidth:320}}>
        <input value={email} onChange={e=>setEmail(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")go();}} type="email" autoComplete="username" placeholder="Email" style={W}/>
        <input value={pw} onChange={e=>setPw(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")go();}} type="password" autoComplete="current-password" placeholder="Password" style={W}/>
        {err&&<div style={{fontSize:11,color:"#d81f2a",fontWeight:700,marginBottom:8,lineHeight:1.4}}>{err}</div>}
        <button onClick={go} disabled={busy} style={{width:"100%",background:busy?T.border:T.navy,border:"none",borderRadius:10,padding:"12px 0",color:"#fff",fontWeight:900,fontSize:13.5,cursor:busy?"default":"pointer"}}>{busy?"Signing in…":"Sign In"}</button>
        <div style={{fontSize:10,color:T.ghost,textAlign:"center",marginTop:12,lineHeight:1.5}}>Team and partner agents use the same door — your account decides what you see.</div>
      </div>
    </div>
  );
}
// PassLock (a SECOND pnlPass gate) had no callers and is removed with the first —
// an orphaned lock component is how a removed passcode quietly returns.
function DiagCard({T,leads,loans,currentUser,dataSource,lastSaveRef,pendingWritesRef}) {
  const [live,setLive] = useState(null);
  const [busy,setBusy] = useState(false);
  const ping = async () => {
    setBusy(true);
    try {
      const sb = await getSupabase();
      if (!sb) { setLive({err:"getSupabase returned null — not connected"}); setBusy(false); return; }
      const { count, error } = await sb.from("clients").select("*",{count:"exact",head:true});
      if (error) { setLive({err:error.message}); setBusy(false); return; }
      const { data: recent } = await sb.from("clients").select("name,status,stage").order("created_at",{ascending:false}).limit(3);
      setLive({count, recent:recent||[]});
    } catch(e){ setLive({err:String(e?.message||e)}); }
    setBusy(false);
  };
  const byStage = {};
  leads.forEach(l=>{ byStage[l.stage]=(byStage[l.stage]||0)+1; });
  const rowS = {display:"flex",justifyContent:"space-between",fontSize:11,padding:"2px 0"};
  return (
    <div style={{background:"#0B1F3A",border:"2px solid #C9A227",borderRadius:12,padding:"12px 14px"}}>
      <div style={{fontSize:9.5,color:T.gold,fontWeight:900,letterSpacing:"0.09em",textTransform:"uppercase",marginBottom:8}}>🔧 Diagnostics — screenshot this card</div>
      <div style={{color:"#fff"}}>
        <div style={rowS}><span>Build</span><b>{BUILD_TAG}</b></div>
        <div style={rowS}><span>User profile</span><b>{currentUser}</b></div>
        <div style={rowS}><span>Data source</span><b style={{color:dataSource==="supabase"?"#7ee2a8":"#ff9d9d"}}>{dataSource}{dataSource!=="supabase"&&" ⚠️ NOT CONNECTED — nothing persists"}</b></div>
        <div style={rowS}><span>Leads in memory</span><b>{leads.length} ({Object.entries(byStage).map(([s,c])=>`${s}:${c}`).join(" ")})</b></div>
        <div style={rowS}><span>Database records</span><b>{loans.length}</b></div>
        <div style={rowS}><span>Pending writes</span><b>{pendingWritesRef.current}</b></div>
        <div style={{...rowS,flexDirection:"column",gap:2}}><span>Last save result</span><b style={{fontSize:10,wordBreak:"break-word"}}>{lastSaveRef.current}</b></div>
        <button onClick={ping} disabled={busy} style={{marginTop:8,width:"100%",background:T.gold,border:"none",borderRadius:8,padding:"9px 0",color:"#0B1F3A",fontWeight:900,fontSize:12,cursor:"pointer"}}>{busy?"Testing…":"⚡ Test Live Database Connection"}</button>
        {live&&(
          <div style={{marginTop:8,fontSize:10.5,background:"rgba(255,255,255,0.08)",borderRadius:8,padding:"8px 10px"}}>
            {live.err
              ? <span style={{color:"#ff9d9d"}}>✗ {live.err}</span>
              : <span style={{color:"#7ee2a8"}}>✓ Connected · {live.count} client rows · newest: {live.recent.map(r=>`${r.name} (${r.status}/${r.stage})`).join(" · ")}</span>}
          </div>
        )}
      </div>
    </div>
  );
}
// Default NAF processor. One constant: the "Processor Assigned" milestone email will
// overwrite this per file once that Zap is live, so this is a starting value, not a lock.
const DEFAULT_PROCESSOR = "Heidi Marcum";
// Report a failed Supabase WRITE instead of swallowing it. A bare catch{} on an upsert or
// delete is how "it looks saved but isn't" bugs survive for weeks — the user has no signal.
// Reads keep their quiet catch: a failed read shows stale data, which is visible.
const warnWrite = (what) => (e) => {
  const msg = String(e?.message || e || "").slice(0, 80);
  console.warn("write failed:", what, msg);
  try { if (window.__flashSync) window.__flashSync(`\u26a0\ufe0f ${what} didn't save${msg ? " — " + msg : ""}`); } catch {}
};
// 8/26 — "Refinance" and "REFINANCE" were sitting in the realtor field on two
// records and counting as an agent on the scoreboard. Same failure as "NAF Hub":
// a LOAN PURPOSE is not a person. "purchase" is guarded with it because it is the
// other value of the same field and would leak identically; no one is named either.
const SYS_SOURCES = ["naf hub","website","portal","direct","zapier",
                     "refinance","refi","purchase"];
// "NAF Hub" is where an application CAME FROM, not who referred it. Falling back to source
// stamped it into the Realtor field on every app, which then read as a real agent and had
// to be cleared by hand. Anything system-generated resolves to blank instead.
const agentSrc = s => { const t=String(s||"").trim(); return SYS_SOURCES.includes(t.toLowerCase()) ? "" : t; };
// The agent FIELD can also hold a system value on older records (the pre-T7 save path
// wrote "NAF Hub" straight into it), so agentSrc has to clean both sides, not just the
// source fallback. This is what T7 missed.
// A tel:/sms: link needs bare digits. iOS opens Messages from sms:, Android too.
// Returns "" when there's no usable number so the button can hide rather than dead-link.
const smsHref = p => { const d=String(p||"").replace(/[^0-9+]/g,""); return d.length>=10 ? `sms:${d}` : ""; };
const realtorOf = l => agentSrc(l&&l.realtorAgent) || agentSrc(l&&l.source);
// Where a file ENDED, for the referral tally. Deliberately three buckets and no more:
// funded, still live, or dead — anything finer is a stage report, not a scoreboard.
const DEAD_STAGES = ["ghosted","creditrepair","archived","other"];
// Short, fixed and few. A free-text box would give every realtor a different wording
// and the "most common stall" line would never group anything together.
const DEAD_REASONS = ["No response","Credit score","Debt-to-income","Down payment",
                      "Went with another lender","Bought cash","Paused the search",
                      "Could not verify income","Property fell through","Other"];
// Reads the jsonb first, then the legacy top-level field, so records saved either way
// still tally.
const deadReasonOf = l => ((l && l.milestones && l.milestones.deadReason)
                        || (l && l.deadReason) || "").trim();
function realtorOutcome(l){
  if(!l) return null;
  if(l.stage==="closed") return "funded";
  if(DEAD_STAGES.includes(l.stage)) return "dead";
  return "live";
}
// Tallies every record that names a realtor. Returns rows sorted by who sends the most,
// with a pull-through rate so volume and quality read side by side — a realtor sending
// twenty that never close is a different conversation from one sending four that all do.
// Group the tally by agentKey: any key holding more than one spelling is the same
// person entered more than one way. Nothing is guessed — agentKey is the app's own
// matcher, the one the portal and the reconcile loop already trust.
// What the tally COMBINED, so a wrong merge is visible rather than silent.
// Partner tiers. Blake 8/28: "whatever you think is best & can tweak later" — so
// the thresholds live here, in one place, and changing them is four numbers.
// FUNDED is the measure, not leads: someone who sends twenty and closes one is
// not a top partner, and ranking on leads alone would say otherwise.
const REALTOR_TIERS = [
  { key:"core",     label:"Core",     min:10 },
  { key:"active",   label:"Active",   min:4  },
  { key:"emerging", label:"Emerging", min:1  },
];
function realtorTier(r){
  if(!r) return null;
  return REALTOR_TIERS.find(t => (r.funded||0) >= t.min) || null;   // null = no closings yet
}
function realtorDupes(rows){
  return (rows||[])
    .filter(r => r.alts && r.alts.length)
    .map(r => ({
      key: agentKey(r.name) || r.name,
      variants: [{name:r.name, files:(r.spellings||{})[r.name]||r.apps}, ...r.alts],
      apps: r.apps, funded: r.funded, volume: r.volume,
    }))
    .sort((a,b)=>b.apps-a.apps);
}
function realtorTally(leads, loans){
  const by = new Map();
  for(const l of [...(leads||[]), ...(loans||[])]){
    const name = realtorOf(l);
    if(!name) continue;
    const o = realtorOutcome(l);
    if(!o) continue;
    const k = agentKey(name) || name.toLowerCase();
    const r = by.get(k) || {name, apps:0, funded:0, live:0, dead:0, volume:0, reasons:{}, spellings:{}, years:{}};
    if(!r.years) r.years = {};
    r.spellings[name] = (r.spellings[name]||0) + 1;
    r.apps++;
    r[o]++;
    if(o==="funded"){
      const amt = (+l.loanAmount || +l.amount || 0);
      r.volume += amt;
      // The year a loan FUNDED, from its closing date. A funded loan with no
      // closing date still counts in the totals but has no year to sit under, so
      // it is left OUT of the breakdown rather than guessed into one — which is
      // why the per-year funded counts can sum to less than the all-time total.
      const yr = String(l.closingDate||"").slice(0,4);
      if(/^[0-9]{4}$/.test(yr)){
        const y = r.years[yr] || {funded:0, volume:0};
        y.funded += 1; y.volume += amt;
        r.years[yr] = y;
      }
    }
    if(o==="dead"){ const why = deadReasonOf(l) || "Not recorded";
                    r.reasons[why] = (r.reasons[why]||0) + 1; }
    by.set(k, r);
  }
  return [...by.values()]
    .map(r => {
      // Show the spelling that appears most. Ties go to the SHORTEST, so a plain
      // "Dreama Bolin" wins over "Dreama D Bolin" rather than whichever happened
      // to be written first.
      // Built as plain objects rather than Object.entries pairs: tsc types the pair
      // as [string, unknown], so subtracting the counts was two diagnostics.
      const alts = Object.keys(r.spellings)
        .map(n2 => ({name:n2, files:Number(r.spellings[n2])||0}))
        .sort((a,b) => b.files-a.files || a.name.length-b.name.length
                       || a.name.localeCompare(b.name));
      return {...r, name: alts[0].name,
              alts: alts.slice(1),
              pull: r.apps ? Math.round(r.funded / r.apps * 100) : 0};
    })
    .sort((a,b) => b.funded - a.funded || b.apps - a.apps
                   || String(a.name).localeCompare(String(b.name)));
}
// Blake 9/14 — TITLE COMPANY MANAGER. Lists every title company on file with how
// many records use it, and merges near-identical names into one. Matching is
// deliberately conservative: it only GROUPS names that normalise to the same key
// (case, punctuation, and filler words like "the / llc / inc / title / group"
// removed). Nothing merges on its own — every merge is an explicit click, because
// two title companies really can have similar names.
const tcNorm = n => String(n||"").toLowerCase()
  .replace(/[.,&'"\-]/g," ")
  .replace(/\b(the|llc|inc|co|company|of|and)\b/g," ")
  .replace(/\s+/g," ").trim();
function TitleCosCard({T, leads, loans, onMerge}){
  // Blake 9/14 — MANUAL MERGE. The auto-grouping below still flags obvious spelling
  // variants, but it will never connect "TLG" to "The Land Group", or "KY Abstract"
  // to "Kentucky Abstract Title" — abbreviations aren't derivable from the string.
  // So selection is the primary tool: tick the spellings that are one company, pick
  // which name survives, merge. Nothing is guessed on your behalf.
  const [sel,setSel]   = useState([]);
  const [keep,setKeep] = useState("");
  const recs = [...leads, ...loans].filter(r=>String((r&&r.titleCompany)||"").trim());
  const exact = new Map();
  recs.forEach(r=>{
    const raw = String(r.titleCompany).trim();
    const k = raw.toLowerCase();
    const cur = exact.get(k);
    if(cur){ cur.n++; } else exact.set(k, {name:raw, n:1, norm:tcNorm(raw)});
  });
  const all = [...exact.values()].sort((a,b)=> b.n-a.n || a.name.localeCompare(b.name));
  const byNorm = new Map();
  all.forEach(t=>{ const g=byNorm.get(t.norm); if(g) g.push(t); else byNorm.set(t.norm,[t]); });
  const autoDupes = [...byNorm.values()].filter(g=>g.length>1);

  const toggle = nm => setSel(p=>{
    const next = p.includes(nm) ? p.filter(x=>x!==nm) : [...p, nm];
    setKeep(k=> next.includes(k) ? k : (next[0]||""));
    return next;
  });
  const selTotal = all.filter(t=>sel.includes(t.name)).reduce((x,t)=>x+t.n,0);
  const keepN    = (all.find(t=>t.name===keep)||{}).n || 0;

  if(!all.length) return <div style={{fontSize:11,color:T.muted,lineHeight:1.6}}>No title companies on file yet.</div>;
  return (
    <div className="lj-toolrows">
      <div style={{fontSize:10.5,color:T.muted,lineHeight:1.6}}>
        {all.length} title compan{all.length===1?"y":"ies"} across {recs.length} file{recs.length===1?"":"s"}.
        {" "}Tick every spelling of the same company, choose the name to keep, then merge.
      </div>

      {autoDupes.length>0 && (
        <div style={{fontSize:10.5,color:T.gold,fontWeight:700,lineHeight:1.6}}>
          {autoDupes.length} look{autoDupes.length===1?"s":""} like an obvious spelling variant \u2014 already ticked below.
        </div>
      )}

      {/* ── SELECTION BAR ── */}
      {sel.length>0 && (
        <div style={{background:T.inner,border:`1px solid ${PLANET.blue}66`,borderRadius:9,padding:"10px 12px"}}>
          <div style={{fontSize:9.5,fontWeight:800,color:PLANET.blue,letterSpacing:"0.09em",
            textTransform:"uppercase",marginBottom:7}}>
            {sel.length} selected \u00b7 {selTotal} file{selTotal===1?"":"s"}
          </div>
          <div style={{fontSize:10.5,color:T.muted,marginBottom:5}}>Keep this name:</div>
          <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:7}}>
            {sel.map(nm=>(
              <span key={nm} onClick={()=>setKeep(nm)}
                style={{cursor:"pointer",fontSize:11,fontWeight:700,padding:"5px 10px",borderRadius:7,
                  background:keep===nm?PLANET.blue:T.card,color:keep===nm?"#fff":T.text,
                  border:`1px solid ${keep===nm?PLANET.blue:T.border}`}}>{nm}</span>
            ))}
          </div>
          <input value={sel.includes(keep)?"":keep}
            onChange={e=>setKeep(e.target.value)}
            placeholder="\u2026 or type a different name to keep"
            style={{boxSizing:"border-box",width:"100%",marginBottom:9,background:T.card,
              border:`1px solid ${(keep&&!sel.includes(keep))?PLANET.blue:T.border}`,borderRadius:7,
              padding:"7px 10px",color:T.text,fontSize:11.5,fontWeight:700,outline:"none"}}/>
          <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
            <button disabled={sel.length<2||!String(keep||"").trim()}
              onClick={()=>{
                const k = String(keep||"").trim();
                if(!k) return;
                const others = sel.filter(x=>x!==k);
                if(!others.length) return;
                const affected = sel.includes(k) ? selTotal-keepN : selTotal;
                if(window.confirm(`Rename ${others.map(o=>`"${o}"`).join(", ")} to "${k}" on ${affected} file${affected===1?"":"s"}?\n\nThis cannot be undone.`)){
                  onMerge(others, k); setSel([]); setKeep("");
                }
              }}
              style={{background:(sel.length<2||!String(keep||"").trim())?T.border:PLANET.blue,border:"none",borderRadius:8,
                padding:"8px 14px",color:"#fff",fontWeight:800,fontSize:11.5,
                cursor:(sel.length<2||!String(keep||"").trim())?"default":"pointer",fontFamily:"inherit",
                opacity:(sel.length<2||!String(keep||"").trim())?0.6:1}}>
              {sel.length<2 ? "Select 2 or more" : `Merge ${sel.length} into "${String(keep||"").trim()}"`}
            </button>
            <span onClick={()=>{setSel([]);setKeep("");}}
              style={{fontSize:10.5,color:T.ghost,fontWeight:700,cursor:"pointer"}}>Clear</span>
          </div>
        </div>
      )}

      {/* ── THE LIST ── */}
      <div style={{background:T.inner,border:`1px solid ${T.border}`,borderRadius:9,padding:"9px 11px"}}>
        <div style={{fontSize:9.5,fontWeight:800,color:T.muted,letterSpacing:"0.09em",
          textTransform:"uppercase",marginBottom:6}}>All title companies</div>
        {all.map(t=>{
          const on = sel.includes(t.name);
          const flagged = autoDupes.some(g=>g.some(x=>x.name===t.name));
          return (
            <div key={t.name} onClick={()=>toggle(t.name)}
              style={{display:"flex",alignItems:"center",gap:9,fontSize:11.5,cursor:"pointer",
                padding:"6px 6px",margin:"0 -6px",borderTop:`1px solid ${T.border}`,
                background:on?`${PLANET.blue}1A`:"transparent",borderRadius:on?6:0}}>
              <span style={{flexShrink:0,width:14,height:14,borderRadius:4,display:"inline-flex",
                alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:900,
                background:on?PLANET.blue:"transparent",color:"#fff",
                border:`1px solid ${on?PLANET.blue:T.border}`}}>{on?"\u2713":""}</span>
              <span style={{color:T.text,fontWeight:600,minWidth:0,overflow:"hidden",
                textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{t.name}</span>
              {flagged&&<span title="Looks like a spelling variant of another entry"
                style={{flexShrink:0,fontSize:9,fontWeight:800,color:T.gold}}>variant</span>}
              <span style={{marginLeft:"auto",color:T.muted,fontWeight:800,
                fontVariantNumeric:"tabular-nums",flexShrink:0}}>{t.n} file{t.n===1?"":"s"}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
function DuplicatesCard({T, leads, loans, ignored, onIgnore, onOpen}){
  const groups = findDuplicates(leads, loans, ignored);
  if(!groups.length) return <div style={{fontSize:11,color:T.muted,lineHeight:1.6}}>No duplicates found across {leads.length+loans.length} records.</div>;
  return (
    <div className="lj-toolrows">
      <div style={{fontSize:10.5,color:T.muted,lineHeight:1.6}}>
        {groups.length} possible duplicate{groups.length===1?"":"s"}. Open each one to compare, then keep the good file and delete the other — or dismiss if they are genuinely different people.
      </div>
      {groups.slice(0,15).map(g=>(
        <div key={g.sig} style={{background:T.inner,border:`1px solid ${T.border}`,borderRadius:9,padding:"9px 11px"}}>
          <div style={{display:"flex",alignItems:"baseline",gap:8,marginBottom:5}}>
            <span style={{fontSize:11.5,fontWeight:800,color:T.text}}>{g.recs[0].borrower||g.recs[0].name}</span>
            <span style={{fontSize:9.5,fontWeight:800,color:T.gold,letterSpacing:"0.09em",textTransform:"uppercase"}}>same {g.by}</span>
            <span onClick={()=>onIgnore(g.sig)} style={{marginLeft:"auto",fontSize:10,color:T.ghost,fontWeight:700,cursor:"pointer"}}>Not a duplicate</span>
          </div>
          {g.recs.map(r=>(
            <div key={r.id} onClick={()=>onOpen(r)} className="lj-row" style={{display:"flex",alignItems:"center",gap:8,padding:"6px 0",borderTop:`1px solid ${T.border}`,cursor:"pointer"}}>
              <span style={{flex:1,minWidth:0,fontSize:11,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                {r.borrower||r.name} <span style={{color:T.muted}}>{[r._kind==="lead"?"pipeline":"database", STAGE_LABELS[r.stage]||r.stage, r.closingDate?fmtDate(r.closingDate):null].filter(Boolean).join(" \u00b7 ")}</span>
              </span>
              <span style={{fontSize:10,color:T.ghost,whiteSpace:"nowrap"}}>{r.phone||r.email||""}</span>
            </div>
          ))}
        </div>
      ))}
      {groups.length>15&&<div style={{fontSize:10,color:T.ghost,fontWeight:700}}>+{groups.length-15} more</div>}
    </div>
  );
}
function IntegrationsCard({T}){
  const [st,setSt] = useState(null);
  useEffect(()=>{ let dead=false;
    (async()=>{
      // Three real states, not two: the endpoint file may not be in the repo at all
      // (Vercel returns 404/HTML), it may be there without a key, or it may be live.
      const ask = async (path) => {
        try{
          const r = await fetch(path);
          if(r.status===404) return "missing";
          const ct = r.headers.get("content-type")||"";
          if(!ct.includes("json")) return "missing";     // Vercel served the SPA, so no such route
          const j = await r.json();
          return j.configured ? "live" : "nokey";
        }catch(e){ return "missing"; }
      };
      const [rates, property, sms] = await Promise.all([ask("/api/rates?status=1"), ask("/api/property?status=1"), ask("/api/sms")]);
      if(!dead) setSt({rates, property, sms});
    })();
    return ()=>{ dead=true; };
  },[]);
  const ROWS = [
    ["rates","Market rates","Live 30/15-year averages in Settings","api/rates.js","FRED_API_KEY"],
    ["property","Property values","Real values behind Refi Finder and client files","api/property.js","ATTOM_API_KEY"],
    ["sms","Texting","Send milestone texts from the app instead of your phone","api/sms.js","TWILIO_ACCOUNT_SID + TWILIO_AUTH_TOKEN + TWILIO_FROM"],
  ];
  const STATE = {
    live:    { label:"connected",   tone:"green",  next:"" },
    nokey:   { label:"needs a key", tone:"gold",   next:"Add this in Vercel → Settings → Environment Variables:" },
    missing: { label:"not installed", tone:"ghost", next:"Add this file to your repo first:" },
  };
  return (
    <div className="lj-toolrows">
      {ROWS.map(([k,label,what,file,envs])=>{
        const v = st ? st[k] : null;
        const s = STATE[v] || { label:"checking\u2026", tone:"border", next:"" };
        const dot = s.tone==="green" ? T.green : s.tone==="gold" ? T.gold : s.tone==="ghost" ? T.ghost : T.border;
        return (
          <div key={k} style={{display:"flex",alignItems:"flex-start",gap:9,padding:"9px 10px",background:T.inner,border:`1px solid ${T.border}`,borderRadius:9}}>
            <span style={{width:8,height:8,borderRadius:"50%",background:dot,flexShrink:0,marginTop:4}}/>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:11.5,fontWeight:800,color:T.text}}>{label}
                <span style={{marginLeft:6,fontSize:9.5,fontWeight:800,color:dot}}>{s.label}</span>
              </div>
              <div style={{fontSize:10,color:T.muted,marginTop:1,lineHeight:1.5}}>{what}</div>
              {s.next!==""&&(
                <div style={{marginTop:4}}>
                  <div style={{fontSize:9,color:T.muted,fontWeight:700}}>{s.next}</div>
                  <div style={{fontSize:9,color:T.text2,marginTop:1,fontFamily:"ui-monospace,'SF Mono',Menlo,monospace",wordBreak:"break-all"}}>{v==="missing"?file:envs}</div>
                </div>
              )}
            </div>
          </div>
        );
      })}
      <div style={{fontSize:9.5,color:T.ghost,lineHeight:1.6}}>
        These are optional. The app works fully without any of them — each one just adds live data. Keys live in Vercel, never in the app.
      </div>
    </div>
  );
}
// A glyph and one line of description per card. MODULE SCOPE: JSX built during a
// render is a new element every pass. The subtitle is what the card actually does,
