// Finds the same person entered twice. Matches on phone (last 10) first — the strongest
// signal — then email, then a normalized name. Records already merged or dismissed stay quiet.
function findDuplicates(leads=[], loans=[], ignored=[]){
  const dig = s => String(s||"").replace(/[^0-9]/g,"").slice(-10);
  const low = s => String(s||"").trim().toLowerCase();
  const nm  = s => low(s).replace(/[^a-z ]/g,"").replace(/\s+/g," ").trim();
  const all = [...leads.map(l=>({...l, _kind:"lead"})), ...loans.map(l=>({...l, _kind:"loan"}))]
    .filter(r=>r && r.id && r.stage!=="archived");
  const groups = new Map();
  const push = (key, rec) => { if(!key) return; if(!groups.has(key)) groups.set(key,[]); const g=groups.get(key); if(!g.some(x=>x.id===rec.id)) g.push(rec); };
  all.forEach(r=>{
    const p = dig(r.phone);       if(p.length===10) push("p:"+p, r);
    const e = low(r.email);       if(e && e.includes("@")) push("e:"+e, r);
    const n = nm(r.borrower||r.name); if(n && n.includes(" ")) push("n:"+n, r);
  });
  const seen = new Set(), out = [];
  for(const [key, recs] of groups){
    if(recs.length < 2) continue;
    const sig = recs.map(r=>r.id).sort().join("|");
    if(seen.has(sig) || ignored.includes(sig)) continue;
    seen.add(sig);
    out.push({ key, sig, by: key[0]==="p"?"phone":key[0]==="e"?"email":"name", recs });
  }
  return out.sort((a,b)=> (a.by==="phone"?0:a.by==="email"?1:2) - (b.by==="phone"?0:b.by==="email"?1:2));
}
// onType fires on every keystroke so a typed address saves even when the borrower's
// street has no match in the geocoder (rural KY, new construction, private roads).
// onPick only adds the extra fields — city, state, ZIP — when a suggestion IS chosen.
const ADDR_W = 280;   // the floating suggestion list's width
function AddressAutocomplete({value, onPick, onType, T, style}){
  const [q,setQ] = useState(value||"");
  const [list,setList] = useState([]);
  const [open,setOpen] = useState(false);
  const [busy,setBusy] = useState(false);
  const tRef = useRef(null);
  // Blake 8/17: the list sat directly under the field at full width with no scroll,
  // so it buried the fields below and he couldn't finish typing. It now floats to the
  // SIDE of the field, scrolls, and is portalled out so nothing clips it.
  const boxRef  = useRef(null);
  const [rect,setRect] = useState(null);
  useLayoutEffect(()=>{
    if(!open){ setRect(null); return; }
    let frame = 0;
    const read = () => { frame=0; const el=boxRef.current; if(!el) return;
      const r = el.getBoundingClientRect();
      const next = {left:Math.round(r.left), right:Math.round(r.right),
                    top:Math.round(r.top), bottom:Math.round(r.bottom), w:Math.round(r.width)};
      // same reference when nothing moved, or every scroll event re-renders
      setRect(p => (p && p.left===next.left && p.top===next.top && p.bottom===next.bottom) ? p : next);
    };
    const onMove = () => { if(frame) return; frame = requestAnimationFrame(read); };
    read();
    window.addEventListener("scroll", onMove, true);
    window.addEventListener("resize", onMove);
    return ()=>{ if(frame) cancelAnimationFrame(frame);
      window.removeEventListener("scroll", onMove, true); window.removeEventListener("resize", onMove); };
  },[open, list.length]);
  useEffect(()=>{ setQ(value||""); }, [value]);
  useEffect(()=>()=>{ if(tRef.current) clearTimeout(tRef.current); },[]);
  const search = (text) => {
    if(tRef.current) clearTimeout(tRef.current);
    if(String(text).trim().length < 6){ setList([]); setOpen(false); return; }
    tRef.current = setTimeout(async()=>{
      setBusy(true);
      try{
        const r = await fetch(`/api/address?q=${encodeURIComponent(text)}`);
        const j = await r.json();
        setList((j.results||[]).slice(0,5)); setOpen(true);   // five is enough to pick from
      }catch(e){ setList([]); }
      setBusy(false);
    }, 450);        // debounce: one lookup after typing stops, not one per keystroke
  };
  return (
    <div ref={boxRef} style={{position:"relative"}}>
      <input value={q} placeholder="Start typing the address…"
        onChange={e=>{ setQ(e.target.value); onType && onType(e.target.value); search(e.target.value); }}
        onBlur={()=>setTimeout(()=>setOpen(false),180)}
        style={style}/>
      {busy&&<span style={{position:"absolute",right:9,top:9,fontSize:9.5,color:T.ghost,fontWeight:700}}>…</span>}
      {open&&rect&&list.length>0&&(
        createPortal(
        <div style={{position:"fixed",
          // beside the field when there is room to its right, otherwise tucked back
          // inside the viewport; never on top of the fields underneath it
          left: Math.min(Math.max(8, rect ? rect.right + 8 : 8), Math.max(8, window.innerWidth - ADDR_W - 8)),
          top:  Math.min(Math.max(8, rect ? rect.top - 2 : 8), Math.max(8, window.innerHeight - 230)),
          width: ADDR_W, maxHeight: 218, overflowY: "auto", overscrollBehavior: "contain",
          zIndex:9002,background:T.card,border:`1px solid ${T.border}`,borderRadius:9,boxShadow:"0 10px 26px rgba(0,0,0,0.3)"}}>
          {list.map((r,i)=>(
            <div key={i} onMouseDown={e=>{ e.preventDefault(); const v=r.street||r.line; setQ(v); setOpen(false); onType&&onType(v); onPick&&onPick(r); }}
              style={{padding:"7px 10px",borderTop:i?`1px solid ${T.border}`:"none",cursor:"pointer",fontSize:11.5,color:T.text}}>
              <div style={{fontWeight:700}}>{r.street||r.line}</div>
              <div style={{fontSize:10,color:T.muted,marginTop:1}}>{[r.city,r.state,r.zip].filter(Boolean).join(", ")}</div>
            </div>
          ))}
        </div>, document.body)
      )}
    </div>
  );
}
function PropertyLookup({lead, T, onApply}){
  const [st,setSt] = useState(null);
  const addr = String(lead?.address||"").trim();
  if(!addr) return null;
  return (
    <div style={{marginTop:6}}>
      <button onClick={async()=>{
        setSt({busy:true});
        try{
          const q = new URLSearchParams({address:addr, city:lead.city||"", state:lead.state||""});
          const r = await fetch(`/api/property?${q}`); const j = await r.json();
          if(!j.configured) return setSt({note:"Add ATTOM_API_KEY in Vercel to use this"});
          if(!j.found)      return setSt({note:j.error||"No record found for that address"});
          setSt({data:j});
        }catch(e){ setSt({note:"Add api/property.js to your repo to use this"}); }
      }} style={{background:"transparent",border:`1px solid ${T.border}`,borderRadius:8,padding:"6px 10px",color:T.text2,fontWeight:800,fontSize:10,cursor:"pointer"}}>
        {st&&st.busy ? "Looking up\u2026" : "Look up property"}
      </button>
      {st&&st.note&&<span style={{marginLeft:8,fontSize:9.5,color:T.ghost,fontWeight:700}}>{st.note}</span>}
      {st&&st.data&&(
        <div style={{marginTop:6,background:T.inner,border:`1px solid ${T.border}`,borderRadius:8,padding:"8px 10px",fontSize:10.5,color:T.muted,lineHeight:1.6}}>
          {st.data.value ? <b style={{color:T.text,fontSize:12}}>{"$"+Math.round(st.data.value).toLocaleString()}</b> : "No value estimate"}
          {st.data.valueRange&&<span> {"\u00b7"} range {"$"+Math.round(st.data.valueRange[0]/1000)+"K"}{"\u2013"}{"$"+Math.round(st.data.valueRange[1]/1000)+"K"}</span>}
          <div>{[st.data.beds&&`${st.data.beds} bd`, st.data.baths&&`${st.data.baths} ba`, st.data.sqft&&`${Number(st.data.sqft).toLocaleString()} sqft`, st.data.yearBuilt&&`built ${st.data.yearBuilt}`].filter(Boolean).join(" \u00b7 ")}</div>
          {st.data.lastSale&&<div>Last sold {"$"+Number(st.data.lastSale.amount).toLocaleString()}{st.data.lastSale.date?` \u00b7 ${st.data.lastSale.date}`:""}</div>}
          {st.data.value&&onApply&&(
            <button onClick={()=>onApply(Math.round(st.data.value))} style={{marginTop:6,background:T.navy,border:"none",borderRadius:7,padding:"6px 10px",color:"#fff",fontWeight:800,fontSize:10,cursor:"pointer"}}>Use as appraised value</button>
          )}
        </div>
      )}
    </div>
  );
}
function DetailCell({lb,val,fld,type,opts,fmt,cap,num,editMode,editFields,ef,LB,IN,RO,dim,dimNote}){
  // `dim` greys a field that does not apply to this file — a refinance has no realtor
  // and no purchase price. It stays VISIBLE and keeps whatever value it already had,
  // so nothing is silently destroyed; it just can't be edited.
  if(dim) return (
    <div style={{minWidth:0,opacity:0.42}} title={dimNote||"Not used on a refinance"}>
      <div style={LB}>{lb}</div>
      <div style={{...RO,fontStyle:"italic",color:"inherit"}}>{dimNote||"n/a"}</div>
    </div>
  );
  return (
    <div style={{minWidth:0}}>
      <div style={LB}>{lb}</div>
      {editMode ? (
        opts ? <select value={editFields[fld]||""} onChange={e=>ef(fld,e.target.value)} style={{...IN,cursor:"pointer"}}>{opts.map(o=><option key={o} value={o}>{o}</option>)}</select>
             : <input value={editFields[fld]??""} onChange={e=>ef(fld, cap?String(e.target.value).toUpperCase().slice(0,cap):e.target.value)} type={type||"text"} inputMode={num?"decimal":undefined} style={IN}/>
      ) : <div style={RO}>{(fmt?fmt(val):val)||"\u2014"}</div>}
    </div>
  );
}
// An empty list should explain itself. Blank space reads as broken — especially in a demo.
// Shown while data is still arriving. Without this, an empty-because-loading list would
// hit the empty state and wrongly announce "no funded loans yet".
function SkeletonRows({T, rows=5, height=54}){
  return (
    <div aria-busy="true" style={{display:"flex",flexDirection:"column",gap:8}}>
      {Array.from({length:rows}).map((_,i)=>(
        <div key={i} style={{height,background:T.card,border:`1px solid ${T.border}`,borderRadius:12,padding:"12px 14px",overflow:"hidden",opacity:1-(i*0.12)}}>
          <div className="lj-shimmer" style={{width:`${58-i*4}%`,height:11,borderRadius:5,background:T.inner}}/>
          <div className="lj-shimmer" style={{width:`${34-i*3}%`,height:9,borderRadius:5,background:T.inner,marginTop:7}}/>
        </div>
      ))}
    </div>
  );
}
