const OLD_STATUS_MAP = {"Need to Review":"","Review":"","Waiting for Docs / Information":"W for Docs","Waiting for Completed App":"W for App","W for Information":"W for Info","Waiting for Information":"W for Info","VOE":"W for VOEs","Working on VOE":"W for VOEs","Working on VOEs":"W for VOEs","New Loan":"New Loans"};
// ─── TURN TIMES ───────────────────────────────────────────────────────────────
// Days between consecutive milestone stamps, across funded files. Everything here
// reads stamps the app already writes; no new field, no new SQL.
//
// MEDIAN, not mean: one file that sat 60 days in underwriting would drag an average
// far enough to hide what a normal file looks like.
const TURN_STEPS = [
  ["underContract","disclosuresRequested","Contract \u2192 Disclosures Req."],
  ["disclosuresRequested","disclosuresSigned","Disclosures Req. \u2192 Signed"],
  ["disclosuresSigned","sentToScrub","Signed \u2192 Scrub"],
  ["sentToScrub","sentToSetup","Scrub \u2192 Set Up"],
  ["sentToSetup","sentToProcessing","Set Up \u2192 Processing"],
  ["sentToProcessing","sentToUW","Processing \u2192 Underwriting"],
  ["sentToUW","uwApproval","Underwriting \u2192 Approval"],
  ["uwApproval","clearToClose","Approval \u2192 Clear to Close"],
];
// The appraisal runs ALONGSIDE the file rather than in the chain, so it is measured
// and shown separately instead of being added into the cycle total.
const TURN_APPRAISAL = [
  ["underContract","appraisalOrdered","Contract \u2192 Appraisal Ordered"],
  ["appraisalOrdered","appraisalReceived","Ordered \u2192 Appraisal Received"],
];
const daysBetween = (a,b) => {
  if(!a||!b) return null;
  const d1=dayOf(a), d2=dayOf(b);
  if(!d1||!d2||isNaN(d1)||isNaN(d2)) return null;
  const d=(d2-d1)/86400000;
  return d<0 ? null : Math.round(d*10)/10;   // a backwards stamp is a correction, not a duration
};
const median = a => {
  const v=a.filter(x=>x!=null).sort((x,y)=>x-y);
  if(!v.length) return null;
  const m=Math.floor(v.length/2);
  return v.length%2 ? v[m] : Math.round(((v[m-1]+v[m])/2)*10)/10;
};
function turnTimes(loans, fromIso, toIso){
  const inWindow = (loans||[]).filter(l =>
    l.stage==="closed" && l.closingDate && l.closingDate>=fromIso && l.closingDate<=toIso &&
    l.milestones && typeof l.milestones==="object");
  const step = (list) => list.map(([a,b,label])=>{
    const gaps = inWindow.map(l=>daysBetween(l.milestones[a], l.milestones[b]));
    const n = gaps.filter(x=>x!=null).length;
    return { a, b, label, days: median(gaps), n };
  });
  const rows = step(TURN_STEPS), appr = step(TURN_APPRAISAL);
  // Cycle = contract stamp to actual closing date, measured per file then medianed —
  // NOT the sum of the medians, which would overstate it.
  const cycle = median(inWindow.map(l=>daysBetween(l.milestones.underContract, l.closingDate)));
  return { rows, appr, cycle, files: inWindow.length,
           stamped: inWindow.filter(l=>l.milestones.underContract).length };
}
