function ProductionCard({T, loans, prod, onSavePull}) {
  const num = v => parseFloat(String(v||"").replace(/[^0-9.]/g,""))||0;
  const isBond = l => /khc|bond/i.test(l.loanType||"");   // bond firsts carry a DPA 2nd lien — counted IN ADDITION to the first, never instead
  const computeMonth = (mk) => {
    const rows = loans.filter(l=>l.stage==="closed" && (l.closingDate||"").startsWith(mk));
    return { volume: rows.reduce((s,l)=>s+(parseFloat(l.amount)||parseFloat(l.loanAmount)||0),0),
             units: rows.length, seconds: rows.filter(isBond).length };
  };
  const curMk = new Date().toISOString().slice(0,7);
  const curYr = curMk.slice(0,4);
  // ── current year: full month-by-month ──
  const mks = Array.from({length:12},(_,i2)=>`${curYr}-${String(i2+1).padStart(2,"0")}`);
  const rows = mks.map(mk=>{
    const st = prod.find(p=>p.month===mk);
    if (st && st.volume!=null) return {mk, ...st, live:false};
    if (mk===curMk) { const c=computeMonth(mk); return {mk, ...c, pulls:st?st.pulls:null, live:true}; }
    if (st) return {mk, volume:null, units:null, seconds:null, pulls:st.pulls, live:false};
    return null;
  }).filter(Boolean).filter(r=>r.volume!=null);   // pulls-only months no longer render a row
  const withData = rows.filter(r=>r.volume!=null);
  const tot = { v:withData.reduce((s,r)=>s+r.volume,0), u:withData.reduce((s,r)=>s+r.units,0), s2:withData.reduce((s,r)=>s+r.seconds,0), p:rows.reduce((s,r)=>s+(r.pulls||0),0) };
  const n2 = withData.length||1;
  // ── prior years: condensed totals ──
  const priorYears = [...new Set(prod.map(p=>p.month.slice(0,4)))].filter(y=>y<curYr).sort().reverse().map(y=>{
    const ms = prod.filter(p=>p.month.startsWith(y)&&p.volume!=null);
    return { y, v:ms.reduce((s,p)=>s+p.volume,0), u:ms.reduce((s,p)=>s+(p.units||0),0), s2:ms.reduce((s,p)=>s+(p.seconds||0),0), p:ms.reduce((s,p)=>s+(p.pulls||0),0), n:ms.length };
  });
  const $k = v => "$"+Math.round(v).toLocaleString();
  const cellH={fontSize:9.5,color:T.muted,fontWeight:800,textTransform:"uppercase",textAlign:"right",padding:"3px 4px"};
  const cellD={fontSize:10.5,fontFamily:"ui-monospace,'SF Mono',Menlo,monospace",fontWeight:700,color:T.text,textAlign:"right",padding:"3px 4px"};
  return (
    <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,overflow:"hidden",marginBottom:14}}>
      <div style={{background:`${T.navy}16`,borderBottom:`2px solid ${T.navy}`,padding:"9px 14px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <span style={{fontSize:9.5,fontWeight:900,color:T.navy,letterSpacing:"0.09em",textTransform:"uppercase"}}>🏠 NAF Production · {curYr}</span>
        <span style={{fontSize:9,color:T.muted,fontWeight:700}}>2nd = bond (KHC) DPA lien</span>
      </div>
      <div style={{padding:"6px 10px 10px",overflowX:"auto"}}>
        <div style={{display:"grid",gridTemplateColumns:"58px 1.5fr 0.85fr 0.8fr 0.85fr",minWidth:370}}>
          <div/><div style={cellH}>Funded Volume</div><div style={cellH}>Units</div><div style={cellH}>2NDs</div><div style={cellH}>Total</div>
          {rows.map(r=>(<Fragment key={r.mk}>
            <div style={{fontSize:10.5,fontWeight:800,color:T.text,padding:"3px 4px"}}>{new Date(r.mk+"-15").toLocaleDateString("en-US",{month:"short",year:"2-digit"})}{r.live&&<span style={{fontSize:9,color:"#b07a2a",fontWeight:900,marginLeft:3}}>LIVE</span>}</div>
            <div style={cellD}>{r.volume!=null?$k(r.volume):"—"}</div>
            <div style={cellD}>{r.units!=null?r.units:"—"}</div>
            <div style={cellD}>{r.seconds!=null?r.seconds:"—"}</div>
            <div style={{...cellD,fontWeight:900}}>{r.volume!=null?(r.units+r.seconds):"—"}</div>
          </Fragment>))}
          <div style={{fontSize:9,fontWeight:900,color:T.navy,padding:"6px 4px 3px",borderTop:`2px solid ${T.navy}`,textTransform:"uppercase"}}>Totals</div>
          <div style={{...cellD,fontWeight:900,borderTop:`2px solid ${T.navy}`,paddingTop:6}}>{$k(tot.v)}</div>
          <div style={{...cellD,fontWeight:900,borderTop:`2px solid ${T.navy}`,paddingTop:6}}>{tot.u}</div>
          <div style={{...cellD,fontWeight:900,borderTop:`2px solid ${T.navy}`,paddingTop:6}}>{tot.s2}</div>
          <div style={{...cellD,fontWeight:900,borderTop:`2px solid ${T.navy}`,paddingTop:6}}>{tot.u+tot.s2}</div>
          <div style={{fontSize:9,fontWeight:900,color:T.muted,padding:"3px 4px",textTransform:"uppercase"}}>Averages</div>
          <div style={{...cellD,color:T.muted}}>{$k(tot.v/n2)}</div>
          <div style={{...cellD,color:T.muted}}>{(tot.u/n2).toFixed(1)}</div>
          <div style={{...cellD,color:T.muted}}>{(tot.s2/n2).toFixed(1)}</div>
          <div style={{...cellD,color:T.muted}}>{((tot.u+tot.s2)/n2).toFixed(1)}</div>
          {priorYears.length>0&&<>
            <div style={{gridColumn:"1 / -1",fontSize:9.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.07em",padding:"10px 4px 3px",borderBottom:`1px solid ${T.border}`}}>Prior Years</div>
            {priorYears.map(py=>(<Fragment key={py.y}>
              <div style={{fontSize:10.5,fontWeight:900,color:T.text2,padding:"3px 4px"}}>{py.y}<span style={{fontSize:9,color:T.ghost,fontWeight:700,marginLeft:3}}>{py.n} mo</span></div>
              <div style={cellD}>{$k(py.v)}</div>
              <div style={cellD}>{py.u}</div>
              <div style={cellD}>{py.s2}</div>
              <div style={{...cellD,fontWeight:900}}>{py.u+py.s2}</div>
            </Fragment>))}
          </>}
        </div>
      </div>
    </div>
  );
}
const STAGE_ORDER_SYNC = ["new","contacted","scrub","setup","processing","ctc"];
const STAGE_MILESTONE  = {contacted:"underContract",scrub:"sentToScrub",setup:"sentToSetup",processing:"sentToProcessing",ctc:"clearToClose"};
function syncStageMilestones(ms, newStage){
  if(!STAGE_ORDER_SYNC.includes(newStage)) return ms||{};   // onhold/closed/archived: leave untouched
  const idx = STAGE_ORDER_SYNC.indexOf(newStage);
  const out = {...(ms||{})};
  const d0 = new Date();
  const today = `${d0.getFullYear()}-${String(d0.getMonth()+1).padStart(2,"0")}-${String(d0.getDate()).padStart(2,"0")}`;
  STAGE_ORDER_SYNC.forEach((s,i)=>{
    const mid = STAGE_MILESTONE[s]; if(!mid) return;
    // Sticky milestones: stamp only when the date is missing. Established dates are never
    // overwritten by stage moves, and moving a file back never reverts later milestones —
    // tap the milestone circle to edit or clear a date by hand.
    if(i<=idx && (!out[mid] || typeof out[mid]!=="string")) out[mid] = today;
  });
  return out;
}
function migratePnlProducts(savedP){
  savedP = savedP || {};
  const P = {...PNL_DEFAULTS.products, ...savedP};
  if (savedP["FHA/USDA"] !== undefined) {   // legacy combined bucket: carry its margin to both unless set separately
    if (savedP["FHA"]  === undefined) P["FHA"]  = savedP["FHA/USDA"];
    if (savedP["USDA"] === undefined) P["USDA"] = savedP["FHA/USDA"];
  }
  delete P["FHA/USDA"];
  return P;
}
