  const shiftMonth = (m, delta) => { const p=String(m||"").split("-"); const y=parseInt(p[0])||new Date().getFullYear(); const mo=parseInt(p[1])||1; const d=new Date(y, mo-1+delta, 15); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`; };
  const monthLabel = m => new Date(m+"-15").toLocaleDateString("en-US",{month:"short",year:"2-digit"});
  const netB = e => (e.branch||0) - (e.concession||0);
  const inpS={boxSizing:"border-box",width:"100%",background:T.inner,border:`1px solid ${T.inputBorder}`,borderRadius:8,padding:"8px 10px",color:T.text,fontSize:12.5,fontWeight:600,outline:"none"};
