const fmt$      = n => new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(n||0);
const initials  = n => n.split(/[\s,]+/).filter(Boolean).map(p=>p[0]).slice(0,2).join("").toUpperCase();
const avatar    = n => {
  const k = String(n||"").trim();
  const hit = Object.keys(TEAM_COLORS).find(x=>x.toLowerCase()===k.toLowerCase());
  if (hit) return TEAM_COLORS[hit];
  const PAL = ["#0a6b34","#8a4f9e","#b5457a","#0f6f8f","#a35a1e","#2f7a6a"];
  let h=0; for (const ch of k) h=(h*31+ch.charCodeAt(0))>>>0;
  return k ? PAL[h%PAL.length] : "#787e88";
};
// An unknown id used to return stages[0], which quietly mislabelled the file as whatever
// happened to be first. Return the id itself instead — wrong-looking beats confidently wrong.
const stageFrom = (stages,id) => stages.find(s=>s.id===id)
  || (id ? { id, label: (STAGE_LABELS && STAGE_LABELS[id]) || String(id), color:"#6b7280" } : stages[0]);
if (typeof document !== "undefined") document.title = "Henderson Team CRM";
const uid       = () => `${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
