// Days a lead has sat in its current stage
// One dot colour per loan type, spread around the wheel from the theme's own accent so it
// stays in-family on all 21 schemes rather than pinning a palette that fights the chrome.
// Maps a zoom + pan into BOTH the preview's CSS box and the canvas source rect.
// One function, two consumers, so the crop he sees is the crop he gets by construction.
function cropGeom(natW, natH, zoom, ox, oy, VIEW){
  const base  = VIEW / Math.max(1, Math.min(natW, natH));   // "cover" the square
  const scale = base * zoom;
  const dispW = natW * scale, dispH = natH * scale;
  // clamp so the image can never be dragged off the viewport
  const minX = VIEW - dispW, minY = VIEW - dispH;
  const x = Math.min(0, Math.max(minX, ox));
  const y = Math.min(0, Math.max(minY, oy));
  return {
    scale, dispW, dispH, x, y,
    // the same window, expressed in the SOURCE image's own pixels
    sx: -x / scale, sy: -y / scale, sSize: VIEW / scale,
  };
}
function PhotoCropper({src, T, onCancel, onSave}){
  const VIEW = 264;
  const [zoom,setZoom] = useState(1);
  const [off,setOff]   = useState({x:0,y:0});
  const [nat,setNat]   = useState({w:0,h:0});
  const drag = useRef(null);
  const imgRef = useRef(null);
  const g = nat.w ? cropGeom(nat.w, nat.h, zoom, off.x, off.y, VIEW) : null;
  // recentre whenever the zoom changes, so the subject does not drift off
  const setZoomAt = (z) => {
    setZoom(z);
    setOff(o=>{ if(!nat.w) return o;
      const a = cropGeom(nat.w,nat.h,zoom,o.x,o.y,VIEW);
      const b = cropGeom(nat.w,nat.h,z,o.x,o.y,VIEW);
      // keep the CENTRE of the viewport pinned across the zoom
      return { x: o.x - (b.dispW - a.dispW)/2, y: o.y - (b.dispH - a.dispH)/2 };
    });
  };
  const down = (e) => { const p = e.touches ? e.touches[0] : e;
    drag.current = {px:p.clientX, py:p.clientY, ox:off.x, oy:off.y}; };
  const move = (e) => { if(!drag.current) return;
    const p = e.touches ? e.touches[0] : e;
    setOff({ x: drag.current.ox + (p.clientX-drag.current.px),
             y: drag.current.oy + (p.clientY-drag.current.py) });
    if(e.cancelable) e.preventDefault(); };
  const up = () => { drag.current = null; };
  const save = () => {
    const im = imgRef.current; if(!im || !nat.w) return;
    const OUT = 512;
    const gg = cropGeom(nat.w, nat.h, zoom, off.x, off.y, VIEW);
    const c = document.createElement("canvas"); c.width = OUT; c.height = OUT;
    const ctx = c.getContext("2d");
    ctx.imageSmoothingQuality = "high";
    // EXACTLY the window the preview is showing, scaled up to the output size
    ctx.drawImage(im, gg.sx, gg.sy, gg.sSize, gg.sSize, 0, 0, OUT, OUT);
    onSave(c.toDataURL("image/jpeg", 0.9));
  };
  return (
    <div onClick={onCancel} style={{position:"fixed",inset:0,zIndex:600,background:"rgba(0,0,0,0.62)",
      display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div onClick={e=>e.stopPropagation()} style={{background:T.card,borderRadius:14,padding:"18px 18px 16px",
        width:"100%",maxWidth:330,boxShadow:"0 18px 50px rgba(0,0,0,0.35)"}}>
        <div style={{fontSize:10.5,fontWeight:800,letterSpacing:"0.09em",textTransform:"uppercase",
          color:T.text2,marginBottom:4}}>Position headshot</div>
        <div style={{fontSize:11.5,color:T.muted,marginBottom:12}}>Drag to move, slider to zoom. The circle is what appears on the cards.</div>
        {/* THE VIEWPORT. The circle is a ring overlay, so the corners stay visible while
            dragging — you can see what is being cut, not just what survives. */}
        <div onMouseDown={down} onMouseMove={move} onMouseUp={up} onMouseLeave={up}
          onTouchStart={down} onTouchMove={move} onTouchEnd={up}
          style={{position:"relative",width:VIEW,height:VIEW,margin:"0 auto",overflow:"hidden",
            borderRadius:10,background:T.inner,cursor:"grab",touchAction:"none",userSelect:"none"}}>
          <img ref={imgRef} src={src} alt="" draggable={false}
            onLoad={e=>{ const im=e.target;
              setNat({w:im.naturalWidth,h:im.naturalHeight});
              const b = cropGeom(im.naturalWidth,im.naturalHeight,1,0,0,VIEW);
              setOff({ x:(VIEW-b.dispW)/2, y:(VIEW-b.dispH)/2 }); }}
            style={g?{position:"absolute",left:g.x,top:g.y,width:g.dispW,height:g.dispH,
              maxWidth:"none",pointerEvents:"none"}:{opacity:0}}/>
          <div aria-hidden="true" style={{position:"absolute",inset:0,pointerEvents:"none",
            borderRadius:10,boxShadow:`0 0 0 9999px rgba(0,0,0,0.0)`,
            background:`radial-gradient(circle at 50% 50%, rgba(0,0,0,0) ${VIEW/2-1}px, rgba(0,0,0,0.55) ${VIEW/2}px)`}}/>
          <div aria-hidden="true" style={{position:"absolute",inset:0,pointerEvents:"none",
            border:`2px solid rgba(255,255,255,0.9)`,borderRadius:"50%"}}/>
        </div>
        <input type="range" min="1" max="3" step="0.01" value={zoom}
          onChange={e=>setZoomAt(parseFloat(e.target.value))}
          style={{width:"100%",marginTop:14,accentColor:T.text2}}/>
        <div style={{display:"flex",gap:8,marginTop:12}}>
          <button onClick={onCancel} style={{flex:1,background:"transparent",border:`1px solid ${T.border}`,
            borderRadius:9,padding:"10px 0",color:T.muted,fontSize:12,fontWeight:700,cursor:"pointer"}}>Cancel</button>
          <button onClick={save} style={{flex:1,background:T.navy,border:"none",borderRadius:9,
            padding:"10px 0",color:"#fff",fontSize:12,fontWeight:800,cursor:"pointer"}}>Use photo</button>
        </div>
      </div>
    </div>
  );
}
// A file is ELIGIBLE to move when it is under contract and NOT rate-locked — a locked
// loan has to fund where it was locked. Eligibility never sets the tag by itself.
function planetEligible(l){
  return !!l && l.stage==="contacted" && !l.rateLocked;
}
// The pre-contract side of the same flag: pre-approved, parked or credit-repair
// clients Blake wants to keep. Deliberately NOT gated on the 8/31 expiry — that date
// was for under-contract files that had to fund somewhere; a prospect he is keeping
// has no such deadline.
const PLANET_PROSPECT_STAGES = ["preapproved","future","readiness"];
function planetProspect(l){
  return !!l && mtpChoice(l)===true && PLANET_PROSPECT_STAGES.includes(l.stage);
}
// The MTP mark runs out at the end of 8/31/2026. Compared as YYYY-MM-DD strings so it
// cannot drift with the browser timezone the way a Date comparison would.
const MTP_UNTIL = "2026-08-31";
// Stored inside `milestones` (jsonb, round-trips whole) rather than as a top-level
// field, which persistClient's explicit column list would drop. Returns true / false /
// undefined — undefined means "not decided", which is what lets the default apply.
function mtpChoice(l){
  const v = l && l.milestones && l.milestones.mtp;
  if(v===true || v==="in")  return true;
  if(v===false || v==="out") return false;
  return (l && l.movingToPlanet) ? true : undefined;   // legacy top-level flag
}
// Blake 8/24: an unlocked under-contract deal DEFAULTS to the move. An explicit
// opt-out always wins, so pressing Remove is not undone on the next render.
// Blake 8/28: ELIGIBILITY NO LONGER AUTO-ADDS. The list was "every unlocked file
// still Under Contract", so it re-populated itself as files moved through — and
// the files actually being migrated are a fixed, hand-picked set. Membership is
// now an explicit choice only; an unset file is simply not on the list.
//
// planetEligibleRaw is kept because the "+ Add" affordance still uses it to decide
// which files are worth OFFERING, but it no longer decides membership.
function mtpOn(l){
  return mtpChoice(l) === true;
}
function planetEligibleRaw(l){
  return !!l && l.stage==="contacted" && !l.rateLocked;
}
function mtpExpired(today = null){
  return (today || new Date().toISOString().slice(0,10)) > MTP_UNTIL;
}
// MTP shows only while the flag is set, the file is STILL Under Contract, and the date
// has not passed. Moving a file out of Under Contract retires the mark on its own.
function mtpActive(l, today = null){
  return !!l && mtpOn(l) && l.stage==="contacted" && !mtpExpired(today);
}
