const LOCS_LBL = {fontSize:7.5,fontWeight:800,letterSpacing:"0.09em",textTransform:"uppercase",
  color:"#6B7280",marginBottom:2,display:"block"};
const LOCS_INP = {width:"100%",boxSizing:"border-box",padding:"5px 7px",border:"1px solid #DCE2E8",
  borderRadius:5,fontSize:11.5,fontWeight:700,color:"#10203D",background:"#fff",
  fontFamily:"inherit",outline:"none"};
const LOCS_SEC = {fontSize:8.5,fontWeight:900,letterSpacing:"0.10em",textTransform:"uppercase",
  color:"#0B63F6",marginBottom:5,display:"block"};
// Hoisted to module scope (Blake 9/9 — fixed the "kicked out after every letter" bug):
// these used to be defined INSIDE LOCoverSheet's render body, so every keystroke's
// re-render created brand-new Field/Note/List function identities, and React tore
// down and rebuilt the actual <input>/<textarea> DOM nodes each time — dropping
// focus after every single character. A stable, module-level component identity
// fixes it: same function reference every render, so React just updates props.
const LOCSField = ({value, onChange, label, ph = ""}) => (
  <label style={{minWidth:0,display:"block"}}>
    <span style={LOCS_LBL}>{label}</span>
    <input value={value} onChange={e=>onChange(e.target.value)} placeholder={ph||""} style={LOCS_INP}/>
  </label>
);
const LOCSNote = ({value, onChange, label, ph = "", hint = ""}) => (
  <div style={{display:"flex",flexDirection:"column",minWidth:0}}>
    <span style={LOCS_SEC}>{label}</span>
    <textarea value={value} maxLength={LOCS_MAX}
      onChange={e=>onChange(e.target.value.slice(0,LOCS_MAX))} placeholder={ph}
      style={{...LOCS_INP,fontWeight:500,fontSize:10.5,lineHeight:1.42,resize:"none",
        height:104,padding:"6px 8px"}}/>
    <span style={{fontSize:7.5,color:"#98A2B3",marginTop:2,
      display:"flex",justifyContent:"space-between",gap:8}}>
      <span style={{minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{hint}</span>
      <span style={{flexShrink:0,fontVariantNumeric:"tabular-nums",
        color:(value||"").length>LOCS_MAX-40?"#C0392B":"#98A2B3"}}>{(value||"").length} / {LOCS_MAX}</span>
    </span>
  </div>
);
// One doc / item per line — same textarea as Note, but a bigger cap (lists of
// docs run longer than a paragraph note) and no per-char counter, since what
// matters here is the line count, not the character count.
const LOCSList = ({value, onChange, label, ph = ""}) => {
  const n = String(value||"").split("\n").map(s=>s.trim()).filter(Boolean).length;
  return (
    <div style={{display:"flex",flexDirection:"column",minWidth:0}}>
      <span style={LOCS_SEC}>{label}</span>
      <textarea value={value} maxLength={LOCS_LIST_MAX}
        onChange={e=>onChange(e.target.value.slice(0,LOCS_LIST_MAX))} placeholder={ph}
        style={{...LOCS_INP,fontWeight:500,fontSize:10.5,lineHeight:1.42,resize:"none",
          height:104,padding:"6px 8px"}}/>
      <span style={{fontSize:7.5,color:"#98A2B3",marginTop:2}}>{n} item{n===1?"":"s"}</span>
    </div>
  );
};

// Blake 9/9: "between Under Contract and Scrub" — the same linear milestone order
// used everywhere else in the app (NORD, reversed here to chronological). Appraisal
// runs in parallel "any time" and isn't part of this sequence, same as elsewhere.
const LOCS_FILE_RANGE = ["underContract","disclosuresRequested","disclosuresSigned","sentToScrub"];
const LOCS_NORD = ["clearToClose","uwApproval","sentToUW","appraisalReceived","appraisalOrdered",
  "sentToProcessing","sentToSetup","sentToScrub","disclosuresSigned","disclosuresRequested","underContract"];
function locsCurrentMilestone(lead){
  const ms = lead.milestones||{};
  const hit = LOCS_NORD.find(id=>typeof ms[id]==="string" && ms[id]);
  return hit || null;
}
// One seeding function so the initial load AND the "Assign to file" picker fill the
// snapshot fields identically — only the snapshot fields, never notes/numbers/docs
// already typed, so assigning a file mid-draft doesn't erase what's been written.
function locsSnapshotFromLead(lead){
  return {
    buyer:(lead&&(lead.name||lead.borrower))||"",
    loanNo:(lead&&(lead.loanNumber||lead.loanNo))||"",
    loanType:(lead&&lead.loanType)||"",
    agent:(lead&&realtorOf(lead))||"",
    title:(lead&&lead.titleCompany)||"",
    address:(lead&&(lead.propertyAddress||lead.address))||"",
    purpose:(lead&&(lead.loanPurpose||lead.purpose))||"",
    processor:(lead&&lead.processor)||"",
    targetClose:(lead&&lead.closingDate)||"",
    lockStatus:(lead&&lead.rateLocked&&lead.lockExpiry)
      ? ("Locked \u00b7 exp " + lead.lockExpiry) : "",
  };
}

function LOCoverSheet({T, SCHEME, onClose, currentUser, preload, leads, clients, onSaveDoc}){
  // Blake 9/9: preload is one of two shapes now — a full previously-saved letter,
  // reopened from a client's eFolder (real Supabase storage, via onSaveDoc/openClientDoc,
  // the same system every other worksheet in this app already relies on), or a bare lead
  // reference to seed a fresh letter from. `docsNeed` only exists on our own saved shape,
  // never on a lead record, so it's a safe way to tell which one this is.
  const isSavedRecord = !!(preload && typeof preload==="object" && "docsNeed" in preload);
  const [f,setF] = useState(()=>{
    if (isSavedRecord) return {...LOCS_BLANK, ...preload, preparedBy: preload.preparedBy||currentUser||""};
    return {...LOCS_BLANK, ...locsSnapshotFromLead(preload||{}), preparedBy: currentUser||""};
  });
  const [flash,setFlash] = useState("");
  const [savePick,setSavePick] = useState(false);
  const set = (k,v) => setF(x=>({...x,[k]:v}));
  // Files between Under Contract and Scrub — the window Blake actually drafts these
  // in. Not tied to preload at all, so this works regardless of how the sheet opened.
  const assignable = (leads||[])
    .map(l=>({lead:l, ms:locsCurrentMilestone(l)}))
    .filter(x=>x.ms && LOCS_FILE_RANGE.includes(x.ms));
  const assignToFile = (leadId) => {
    const hit = assignable.find(x=>x.lead.id===leadId);
    if (!hit) return;
    setF(x=>({...x, ...locsSnapshotFromLead(hit.lead)}));
    setAssignedClient({id:hit.lead.id, name:hit.lead.name});
    setFlash("Assigned \u00b7 saving"); setTimeout(()=>setFlash(""),1600);
  };
  const toggleWaiver = (w) => setF(x=>({...x,

    waivers: x.waivers.includes(w) ? x.waivers.filter(y=>y!==w) : [...x.waivers, w]}));
  // Blake 9/9: replaces the old localStorage-only save, which was never reliable — every
  // other worksheet in this app (Offer Sheet, Cover Letter, Bank Review, W2, Pre-Approval)
  // persists through onSaveDoc/Supabase, the actual database, not a per-browser cache. This
  // sheet now does the same. `assignedClient` is who this letter is saved under; once set
  // (by a manual save or by Assign to file), every further change autosaves to their real
  // eFolder record. Before that, nothing saves anywhere — Save opens the same client picker
  // every other tool uses, and picking someone both saves immediately and sets the target
  // for autosave from then on.
  const [assignedClient,setAssignedClient] = useState(()=>
    (isSavedRecord && preload._savedClientId) ? {id:preload._savedClientId, name:preload._savedClientName||preload.buyer} : null);
  const latestF = useRef(f);
  useEffect(() => { latestF.current = f; }, [f]);
  const assignedRef = useRef(assignedClient);
  useEffect(() => { assignedRef.current = assignedClient; }, [assignedClient]);
  const saveToClient = (client, quiet) => {
    if (!onSaveDoc || !client) return;
    const rec = {...latestF.current, _savedClientId:client.id, _savedClientName:client.name};
    const label = `Operations Cover Letter \u00b7 ${rec.buyer||client.name} \u00b7 ${new Date().toLocaleDateString()}`;
    onSaveDoc(client.id, client.name, "opscover", label, rec);
    setAssignedClient(client);
    setFlash(quiet ? "Auto-saved" : `Saved to ${client.name}'s file`);
    setTimeout(()=>setFlash(""),1800);
  };
  const save = () => { if (assignedClient) saveToClient(assignedClient,false); else setSavePick(true); };
  const clear = () => { if(window.confirm("Clear every field on this cover sheet?"))
    setF({...LOCS_BLANK, preparedBy: currentUser||""}); };
  useEffect(() => {
    if (!assignedClient) return;   // nothing to autosave to until a file is attached
    const t = setTimeout(() => saveToClient(assignedClient, true), 900);
    return () => clearTimeout(t);
  }, [f, assignedClient]);
  // Flush the last edit (the ~900ms debounce window would otherwise drop it) the moment
  // the sheet closes or the app navigates away from it.
  useEffect(() => () => {
    if (assignedRef.current) saveToClient(assignedRef.current, true);
  }, []);

  // linesOf is a plain helper (not a component), so recreating it each render is
  // harmless — it's only Field/Note/List (now module-level, above) that had to move.
  const linesOf = k => String(f[k]||"").split("\n").map(s=>s.trim()).filter(Boolean);

    // ── RENDER, rebuilt 8/31 ───────────────────────────────────────────────────
  // A DISCLOSURE-TIME snapshot, not a UW handoff. The sheet lands in the eFolder
  // beside LEs and disclosures, so the EXPORT is light with its own tokens — it
  // must look identical whichever theme the app is in when it is exported.
  const S_PAPER="#FFFFFF", S_ALT="#F7F9FC", S_LINE="#DFE5EC",
        S_INK="#1B2027", S_SEC="#4A515A", S_MUT="#6E757E",
        S_BLUE="#0B4FA8", S_AMBER="#9A6400";
  const has = (k) => String(f[k]||"").trim().length > 0;
  const dash = <span style={{color:S_MUT,fontStyle:"italic"}}>&mdash;</span>;
  const Cell = ({k, label, span=1}) => (
    <div style={{gridColumn:`span ${span}`,background:S_PAPER,padding:"7px 10px",minHeight:42}}>
      <div style={{fontSize:7.5,fontWeight:700,letterSpacing:"0.1em",
        textTransform:"uppercase",color:S_MUT}}>{label}</div>
      <div style={{fontSize:11,fontWeight:600,marginTop:3,color:S_INK,lineHeight:1.3,
        fontVariantNumeric:"tabular-nums"}}>{has(k) ? f[k] : dash}</div>
    </div>);
  const Num = ({k, label, unit}) => (
    <div style={{background:S_ALT,border:`1px solid ${S_LINE}`,borderRadius:9,padding:"9px 11px"}}>
      <div style={{fontSize:7.5,fontWeight:700,letterSpacing:"0.1em",
        textTransform:"uppercase",color:S_MUT}}>{label}</div>
      <div style={{fontSize:16,fontWeight:700,marginTop:3,color:S_INK,
        fontVariantNumeric:"tabular-nums"}}>{has(k) ? f[k] : dash}</div>
      <div style={{fontSize:9,color:S_MUT,marginTop:2}}>{unit}</div>
    </div>);
  // Empty notes DROP from the export rather than printing as blank boxes: at
  // disclosure most files only carry income, assets and credit, and a sheet that
  // fits its content reads as finished where six half-empty boxes read as unfinished.
  const NOTE_SECTIONS = [
    ["income","Income"], ["assets","Assets"], ["credit","Credit"],
    ["structure","Structure & compensating factors"],
    ["conversation","Conversation notes"], ["forProcessing","For processing"],
  ];
  const filledNotes = NOTE_SECTIONS.filter(([k])=>has(k));
  const band = (t) => (
    <div style={{fontSize:8.5,fontWeight:800,letterSpacing:"0.13em",textTransform:"uppercase",
      color:S_MUT,display:"flex",alignItems:"center",gap:8,margin:"15px 0 8px"}}>
      <span style={{width:2,height:10,background:S_BLUE,borderRadius:1,flexShrink:0}}/>
      {t}<span style={{flex:1,height:1,background:S_LINE}}/>
    </div>);

  return (
    <div style={{position:"fixed",inset:0,zIndex:400,background:"rgba(10,14,20,0.55)",
      display:"flex",alignItems:"flex-start",justifyContent:"center",overflowY:"auto",padding:"18px 14px"}}
      onClick={onClose}>
      <div onClick={e=>e.stopPropagation()}
        style={{width:"100%",maxWidth:1180,background:T.card,border:`1px solid ${T.border}`,
          borderRadius:14,overflow:"hidden",marginBottom:24}}>

        {/* ── app chrome: stays in the CRM's own theme ── */}
        <div style={{display:"flex",alignItems:"center",gap:10,padding:"14px 18px",
          borderBottom:`1px solid ${T.border}`,flexWrap:"wrap"}}>
          <div style={{flex:1,minWidth:220}}>
            <div style={{fontSize:16,fontWeight:800,color:T.text,letterSpacing:"-0.01em"}}>Operations Cover Letter</div>
            <div style={{fontSize:11.5,color:T.muted,marginTop:2}}>
              Fills from the client file. Type over anything — autosaves as you go. Exports as one JPG for processing and underwriting.</div>
          </div>
          {/* Blake 9/9: assigning a file is what actually fixes "auto-saved but gone when I
              came back" — it gives the sheet a stable record to save under instead of
              depending on whatever context it happened to open with. Scoped to Under
              Contract through Scrub, the window this sheet is actually drafted in. */}
          {assignable.length>0 && (
            <select onChange={e=>{ if(e.target.value) assignToFile(e.target.value); e.target.value=""; }}
              defaultValue="" title="Tie this letter to a specific file so it always saves and reloads correctly"
              style={{background:T.inner,border:`1px solid ${T.border}`,borderRadius:9,padding:"9px 10px",
                color:T.text,fontSize:12,fontWeight:600,cursor:"pointer",fontFamily:"inherit",maxWidth:200}}>
              <option value="">Assign to file…</option>
              {assignable.map(({lead})=>(
                <option key={lead.id} value={lead.id}>{lead.name}{lead.loanNumber||lead.loanNo?` · #${lead.loanNumber||lead.loanNo}`:""}</option>
              ))}
            </select>
          )}
          <button onClick={save} style={{background:T.navy,border:"none",borderRadius:9,
            padding:"9px 16px",color:"#fff",fontSize:12.5,fontWeight:700,cursor:"pointer",
            fontFamily:"inherit",whiteSpace:"nowrap"}}>Save</button>
          {flash&&<span style={{fontSize:11,color:T.text2,fontWeight:700}}>{flash}</span>}
          <button onClick={onClose} title="Close" style={{background:"transparent",border:"none",
            color:T.ghost,fontSize:20,lineHeight:1,cursor:"pointer",padding:"0 2px"}}>{"\u00d7"}</button>
        </div>

        <div className="lj-locs" style={{display:"grid",gridTemplateColumns:"minmax(0,1fr) 600px",
          alignItems:"start"}}>

          {/* ══ INPUT ══════════════════════════════════════════════════ */}
          <div style={{padding:"16px 18px 20px",minWidth:0}}>
            <div style={{fontSize:9.5,fontWeight:800,letterSpacing:"0.12em",textTransform:"uppercase",
              color:T.ghost,marginBottom:9}}>File snapshot</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:9}}>
              <div style={{gridColumn:"span 2"}}><LOCSField value={f.buyer} onChange={v=>set("buyer",v)} label="Borrower(s)"/></div>
              <LOCSField value={f.loanNo} onChange={v=>set("loanNo",v)} label="Loan #"/>
              <LOCSField value={f.loanType} onChange={v=>set("loanType",v)} label="Loan type"/>
              <div style={{gridColumn:"span 4"}}><LOCSField value={f.address} onChange={v=>set("address",v)} label="Property address"/></div>
              <LOCSField value={f.purpose} onChange={v=>set("purpose",v)} label="Purpose" ph="Purchase"/>
              <LOCSField value={f.agent} onChange={v=>set("agent",v)} label="Realtor"/>
              <LOCSField value={f.title} onChange={v=>set("title",v)} label="Title company"/>
              <LOCSField value={f.processor} onChange={v=>set("processor",v)} label="Processor"/>
              <LOCSField value={f.aus} onChange={v=>set("aus",v)} label="AUS" ph="Approve/Eligible"/>
              <LOCSField value={f.lockRate} onChange={v=>set("lockRate",v)} label="Locked @" ph="6.5%"/>
              <LOCSField value={f.lockStatus} onChange={v=>set("lockStatus",v)} label="Lock status"/>
              <LOCSField value={f.preparedBy} onChange={v=>set("preparedBy",v)} label="Prepared by"/>
            </div>
            <div style={{marginTop:9}}>
              <LOCSField value={f.closeTimeline} onChange={v=>set("closeTimeline",v)} label="Closing notes"
                ph="e.g. Target close 9/22 — disclosures out 9/12, appraisal due 9/20, CTC by 9/30"/>
            </div>

            <div style={{fontSize:9.5,fontWeight:800,letterSpacing:"0.12em",textTransform:"uppercase",
              color:T.ghost,margin:"16px 0 9px"}}>Qualifying numbers</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:9}}>
              <LOCSField value={f.qIncome} onChange={v=>set("qIncome",v)} label="Income /mo" ph="6,013"/>
              <LOCSField value={f.qDti} onChange={v=>set("qDti",v)} label="Ratios (DTI front / back)" ph="28.4 / 46.2"/>
              <LOCSField value={f.qScore} onChange={v=>set("qScore",v)} label="Mid score" ph="684"/>
              <LOCSField value={f.qAssets} onChange={v=>set("qAssets",v)} label="Assets verified" ph="14,200"/>
            </div>

            <div style={{fontSize:9.5,fontWeight:800,letterSpacing:"0.12em",textTransform:"uppercase",
              color:T.ghost,margin:"16px 0 9px"}}>Funds to close</div>
            <LOCSField value={f.ftcExpected} onChange={v=>set("ftcExpected",v)} label="Expected funds to close"
              ph="e.g. 3.5% down of purchase price, seller paying full closing"/>
            <div style={{marginTop:10}}>
              <LOCSList value={f.ftcNotes} onChange={v=>set("ftcNotes",v)} label="Notes on funds to close"
                ph={"One per line \u2014 e.g.\nSeller tax bills coming due \u2014 prorate 1/1\u2013close once title confirms amount\nTransfer tax always paid by seller in KY\nWe never do owner's title insurance"}/>
            </div>

            <div style={{fontSize:9.5,fontWeight:800,letterSpacing:"0.12em",textTransform:"uppercase",
              color:T.ghost,margin:"16px 0 9px"}}>
              Documents &amp; AUS
              <span style={{fontWeight:500,letterSpacing:0,textTransform:"none",color:T.ghost,
                marginLeft:8,fontSize:10.5}}>one item per line</span>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
              <LOCSList value={f.docsNeed} onChange={v=>set("docsNeed",v)} label="Docs still outstanding" ph={"One per line \u2014 e.g.\nLOE \u2014 large deposit\nUpdated bank statement"}/>
              <LOCSList value={f.fileNotes} onChange={v=>set("fileNotes",v)} label="Notes on file" ph={"One per line \u2014 e.g.\nCurrent home sold\nMost recent Truist statement in file (8/24)"}/>
            </div>
            <div style={{marginTop:10}}>
              <LOCSNote value={f.ausFindings} onChange={v=>set("ausFindings",v)} label="Notes on AUS findings" ph="Conditions, stips, anything the AUS flagged"/>
            </div>

            <div style={{fontSize:9.5,fontWeight:800,letterSpacing:"0.12em",textTransform:"uppercase",
              color:T.ghost,margin:"16px 0 9px"}}>
              Notes
              <span style={{fontWeight:500,letterSpacing:0,textTransform:"none",color:T.ghost,
                marginLeft:8,fontSize:10.5}}>empty sections are left off the export</span>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
              <LOCSNote value={f.income} onChange={v=>set("income",v)} label="Income" ph="How the income was calculated and what was excluded"/>
              <LOCSNote value={f.assets} onChange={v=>set("assets",v)} label="Assets" ph="What is sourced, seasoned, gifted"/>
              <LOCSNote value={f.credit} onChange={v=>set("credit",v)} label="Credit" ph="Scores, derogatories, anything explained"/>
              <LOCSNote value={f.structure} onChange={v=>set("structure",v)} label="Structure & compensating factors" ph="Why this works"/>
              <LOCSNote value={f.conversation} onChange={v=>set("conversation",v)} label="Conversation notes" ph="What was said that isn't anywhere else"/>
              <LOCSNote value={f.forProcessing} onChange={v=>set("forProcessing",v)} label="For processing" ph="What you want them to do first"/>
            </div>

            <div style={{display:"flex",gap:9,alignItems:"center",marginTop:16,flexWrap:"wrap"}}>
              <button onClick={save} style={{background:T.text2,border:"none",borderRadius:9,
                padding:"10px 16px",color:"#fff",fontSize:12.5,fontWeight:700,cursor:"pointer",
                fontFamily:"inherit"}}>Save</button>
              {assignedClient && (
                <span style={{fontSize:11,color:T.muted,fontWeight:600}}>
                  Saved to {assignedClient.name}'s file — reopen it from there
                </span>
              )}
              {/* Blake 9/9: window.print()'s "Save as PDF" path was unreliable, same class of
                  issue as the income worksheet's PDF button. #locs-sheet (the Export Preview
                  panel) is already a clean, chrome-free, single-page document — capturing it
                  straight to JPG needs no header/footer/margin stripping at all, since there's
                  no app UI or page pagination in that node to begin with. */}
              <button onClick={async()=>{
                  const node = document.getElementById("locs-sheet");
                  if(!node){ if(window.__flashSync) window.__flashSync("⚠️ Nothing to export yet"); return; }
                  try{
                    if(window.__flashSync) window.__flashSync("Building image…");
                    const fname = `operations-cover-letter-${(f.buyer||"letter").replace(/[^a-z0-9]+/gi,"-").toLowerCase()}-${new Date().toISOString().slice(0,10)}.jpg`;
                    const file = await makeJpgFile(node, fname);
                    await deliverFile(file, fname);
                  }catch(e){ if(window.__flashSync) window.__flashSync("⚠️ JPG failed: "+String(e?.message||e).slice(0,60)); }
                }} style={{background:"transparent",
                border:`1px solid ${T.border}`,borderRadius:9,padding:"10px 16px",color:T.text,
                fontSize:12.5,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>📷 Save as JPG</button>
              <span style={{flex:1}}/>
              <button onClick={clear} style={{background:"transparent",border:"none",color:T.ghost,
                fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>Clear</button>
            </div>
          </div>

          {/* ══ EXPORT PREVIEW — light, its own tokens ═════════════════ */}
          <div style={{padding:"16px 18px 20px",background:T.page,borderLeft:`1px solid ${T.border}`}}>
            <div style={{fontSize:9.5,fontWeight:800,letterSpacing:"0.12em",textTransform:"uppercase",
              color:T.ghost,marginBottom:10,display:"flex",alignItems:"center"}}>
              Export preview
              <span style={{marginLeft:"auto",fontWeight:600,letterSpacing:0,textTransform:"none",
                fontSize:10.5}}>one page &middot; 2200 &times; 3000 JPG</span>
            </div>

            <div id="locs-sheet" style={{background:S_PAPER,color:S_INK,
              border:`1px solid ${S_LINE}`,borderRadius:12,overflow:"hidden"}}>
              <div style={{display:"flex",alignItems:"center",gap:13,padding:"15px 18px 13px",
                borderBottom:`2px solid ${S_BLUE}`,background:S_ALT}}>
                <img src={HH_SEAL_2026} alt="" style={{width:50,height:50,flexShrink:0,
                  objectFit:"contain"}}/>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:8.5,fontWeight:700,letterSpacing:"0.16em",
                    textTransform:"uppercase",color:S_BLUE}}>Henderson Team</div>
                  <div style={{fontSize:18,fontWeight:700,letterSpacing:"-0.02em",marginTop:3}}>Operations Cover Letter</div>
                  <div style={{fontSize:10.5,color:S_SEC,marginTop:2}}>Handoff to processing &amp; underwriting</div>
                </div>
                <div style={{flexShrink:0,textAlign:"right",fontSize:9.5,color:S_SEC,lineHeight:1.75}}>
                  Loan #&nbsp; <b style={{color:S_INK}}>{has("loanNo")?f.loanNo:"\u2014"}</b><br/>
                  Prepared by&nbsp; <b style={{color:S_INK}}>{has("preparedBy")?f.preparedBy:"\u2014"}</b><br/>
                  <b style={{color:S_INK}}>{new Date().toLocaleDateString("en-US",
                    {month:"short",day:"numeric",year:"numeric"})}</b>
                </div>
              </div>

              <div style={{padding:"13px 18px 18px"}}>
                {band("File snapshot")}
                <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:1,
                  background:S_LINE,border:`1px solid ${S_LINE}`,borderRadius:9,overflow:"hidden"}}>
                  <Cell k="buyer" label="Borrower(s)" span={2}/>
                  <Cell k="loanType" label="Loan type"/>
                  <Cell k="purpose" label="Purpose"/>
                  <Cell k="address" label="Property" span={2}/>
                  <Cell k="agent" label="Realtor"/>
                  <Cell k="title" label="Title"/>
                  <Cell k="processor" label="Processor"/>
                  <Cell k="aus" label="AUS"/>
                  <Cell k="lockRate" label="Locked @"/>
                  <Cell k="lockStatus" label="Lock status" span={2}/>
                  <Cell k="closeTimeline" label="Closing notes" span={4}/>
                </div>

                {(has("qIncome")||has("qDti")||has("qScore")||has("qAssets")) && (<>
                  {band("Qualifying numbers")}
                  <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:8}}>
                    <Num k="qIncome" label="Income" unit="per month"/>
                    <Num k="qDti" label="DTI" unit="front / back"/>
                    <Num k="qScore" label="Mid score" unit="representative"/>
                    <Num k="qAssets" label="Assets" unit="verified"/>
                  </div>
                </>)}

                {(has("ftcExpected")||linesOf("ftcNotes").length>0) && (<>
                  {band("Funds to close")}
                  {has("ftcExpected") && (
                    <div style={{background:S_ALT,border:`1px solid ${S_LINE}`,borderRadius:9,
                      padding:"9px 11px",marginBottom:linesOf("ftcNotes").length>0?9:0}}>
                      <div style={{fontSize:8.5,fontWeight:700,letterSpacing:"0.09em",
                        textTransform:"uppercase",color:S_MUT}}>Expected funds to close</div>
                      <div style={{fontSize:12,fontWeight:600,marginTop:3,color:S_INK}}>{f.ftcExpected}</div>
                    </div>
                  )}
                  {linesOf("ftcNotes").length>0 && (
                    <div style={{background:S_PAPER,border:`1px solid ${S_LINE}`,borderRadius:9,padding:"9px 11px"}}>
                      {linesOf("ftcNotes").map((d,ix)=>(
                        <div key={ix} style={{display:"flex",gap:6,alignItems:"flex-start",
                          fontSize:10,lineHeight:1.5,color:S_SEC,marginBottom:3}}>
                          <span style={{color:S_MUT,flexShrink:0}}>&#8226;</span><span>{d}</span>
                        </div>))}
                    </div>
                  )}
                </>)}

                {(linesOf("docsNeed").length>0 || linesOf("fileNotes").length>0 || has("ausFindings")) && (<>
                  {band("Documents & AUS")}
                  <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:9,marginBottom:has("ausFindings")?9:0}}>
                    <div style={{background:S_PAPER,border:`1px solid ${S_LINE}`,borderRadius:9,padding:"9px 11px"}}>
                      <div style={{fontSize:8.5,fontWeight:700,letterSpacing:"0.09em",
                        textTransform:"uppercase",color:S_AMBER,marginBottom:6}}>Docs still outstanding</div>
                      {linesOf("docsNeed").length>0 ? linesOf("docsNeed").map((d,ix)=>(
                        <div key={ix} style={{display:"flex",gap:6,alignItems:"flex-start",
                          fontSize:10,lineHeight:1.5,color:S_SEC,marginBottom:3}}>
                          <span style={{color:S_AMBER,flexShrink:0}}>&#9633;</span><span>{d}</span>
                        </div>)) : <div style={{fontSize:10,color:S_MUT,fontStyle:"italic"}}>{"\u2014"}</div>}
                    </div>
                    <div style={{background:S_PAPER,border:`1px solid ${S_LINE}`,borderRadius:9,padding:"9px 11px"}}>
                      <div style={{fontSize:8.5,fontWeight:700,letterSpacing:"0.09em",
                        textTransform:"uppercase",color:S_MUT,marginBottom:6}}>Notes on file</div>
                      {linesOf("fileNotes").length>0 ? linesOf("fileNotes").map((d,ix)=>(
                        <div key={ix} style={{display:"flex",gap:6,alignItems:"flex-start",
                          fontSize:10,lineHeight:1.5,color:S_SEC,marginBottom:3}}>
                          <span style={{color:S_MUT,flexShrink:0}}>&#8226;</span><span>{d}</span>
                        </div>)) : <div style={{fontSize:10,color:S_MUT,fontStyle:"italic"}}>{"\u2014"}</div>}
                    </div>
                  </div>
                  {has("ausFindings") && (
                    <div style={{background:S_PAPER,border:`1px solid ${S_LINE}`,borderRadius:9,padding:"9px 11px"}}>
                      <div style={{fontSize:8.5,fontWeight:700,letterSpacing:"0.09em",
                        textTransform:"uppercase",color:S_BLUE,marginBottom:5}}>Notes on AUS findings</div>
                      <div style={{fontSize:10,lineHeight:1.6,color:S_SEC,
                        whiteSpace:"pre-wrap"}}>{f.ausFindings}</div>
                    </div>
                  )}
                </>)}

                {filledNotes.length>0 && (<>
                  {band("Notes")}
                  <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:9}}>
                    {filledNotes.map(([k,label],ix)=>(
                      <div key={k} style={{background:S_PAPER,border:`1px solid ${S_LINE}`,
                        borderRadius:9,padding:"9px 11px",
                        gridColumn: (ix===filledNotes.length-1 && filledNotes.length%2===1)
                          ? "span 2" : "span 1"}}>
                        <div style={{fontSize:8.5,fontWeight:700,letterSpacing:"0.09em",
                          textTransform:"uppercase",color:S_BLUE,marginBottom:5}}>{label}</div>
                        <div style={{fontSize:10,lineHeight:1.6,color:S_SEC,
                          whiteSpace:"pre-wrap"}}>{f[k]}</div>
                      </div>))}
                  </div>
                </>)}

                <div style={{display:"flex",gap:12,marginTop:14,paddingTop:11,
                  borderTop:`1px solid ${S_LINE}`,fontSize:8.5,color:S_MUT}}>
                  <div style={{flex:1}}>
                    <div style={{borderBottom:"1px solid #9AA2AB",height:16,maxWidth:190}}/>
                    <div style={{marginTop:4,letterSpacing:"0.09em",textTransform:"uppercase"}}>
                      {has("preparedBy")?f.preparedBy:"Prepared by"} &middot; NMLS #{CP_LO_NMLS}
                    </div>
                  </div>
                  <div style={{textAlign:"right",lineHeight:1.7}}>
                    Henderson Team &middot; {CP_COMPANY} &middot; NMLS #{CP_COMPANY_NMLS}<br/>
                    Equal Housing Lender &middot; internal working document, not a commitment to lend
                  </div>
                </div>
              </div>
            </div>
          </div>

        </div>
      </div>
      {savePick && <SaveToEFolder T={T} clients={clients||[]} title="Save Operations Cover Letter to client"
        onPick={c=>{ saveToClient(c,false); setSavePick(false); }} onClose={()=>setSavePick(false)}/>}
    </div>
  );
}

function typeDot(type, accent){
  // TBD is NOT a programme, so it takes a neutral grey rather than a hue. Without this
  // it would land on index 0 — the slot Conventional used to occupy — and the two would
  // be the same colour, which is the confusion this whole change is meant to remove.
  if (fmtLoanType(type) === LOAN_TYPE_TBD) return "#98A2B3";
  const i = Math.max(0, LOAN_TYPES.indexOf(String(type||"").trim()));
  const h = String(accent||"#0A57D0").replace("#","");
  const [r,g,b] = [0,2,4].map(k=>parseInt(h.slice(k,k+2),16)/255);
  const mx=Math.max(r,g,b), mn=Math.min(r,g,b), d=mx-mn;
  let hue = d===0 ? 0 : mx===r ? ((g-b)/d)%6 : mx===g ? (b-r)/d+2 : (r-g)/d+4;
  hue = (hue*60 + i*34 + 360) % 360;
  // fixed S/L so every dot reads at the same weight; only the hue moves
  const f = n => { const k=(n+hue/30)%12, a=0.52*Math.min(0.46,1-0.46);
    return Math.round(255*(0.46 - a*Math.max(-1,Math.min(k-3,Math.min(9-k,1))))); };
  return `rgb(${f(0)},${f(8)},${f(4)})`;
}
// The newest note, which is the closest thing the record has to a "last action".
// The most recent moment this file was worked. updatedAt is the real stamp (written by
// saveLead); stageEnteredAt and createdAt are the fallbacks that let files saved before
// the stamp existed still sort sensibly instead of all tying at zero.
// The order Blake reads the page in. Anything unlisted shares the last rank, where
// "doesn't matter" means they simply fall through to the last-touched tiebreak.
const MV_ORDER = ["New Loans", "Under Contract", "Offer Submitted", "Needs Numbers"];
const mvRank = l => {
  if(!l) return MV_ORDER.length;
  // Under Contract is a STAGE, not a status — checked first so a contacted file cannot
  // also match a leftover newStatus from before it went under contract.
  if(l.stage === "contacted") return MV_ORDER.indexOf("Under Contract");
  const i = MV_ORDER.indexOf(normStatus(l.newStatus));
  return i < 0 ? MV_ORDER.length : i;
};
// Blake 9/12 — A "second" for production-reporting purposes. This predicate was
// previously defined only inside the Analytics tab, so the Dashboard counted 2nds
// in its Units/Volume while Analytics excluded them, and the two pages disagreed.
// Hoisted here so BOTH read one definition. Changing what counts as a second is
// now a single edit, not two that can fall out of sync.
const isSecondLoan = l => /khc|2nd|second|heloc/i.test((l && l.loanType) || "");
const touchedAt = lead => {
  const vals = [lead && lead.updatedAt, lead && lead.stageEnteredAt, lead && lead.createdAt]
    .map(v => { const t = v ? Date.parse(v) : NaN; return isNaN(t) ? 0 : t; });
  return Math.max(0, ...vals);
};
// "28m ago" / "2h ago" / "Yesterday". Reads touchedAt, which is the stamp the app
// already sorts by — no new field, no invented recency.
const sinceStr = (ms) => {
  if(!ms) return "\u2014";
  const s = Math.max(0, Math.floor((Date.now() - ms) / 1000));
  if (s < 60)      return "just now";
  if (s < 3600)    return Math.floor(s/60) + "m ago";
  if (s < 86400)   return Math.floor(s/3600) + "h ago";
  if (s < 172800)  return "Yesterday";
  if (s < 604800)  return Math.floor(s/86400) + "d ago";
  return new Date(ms).toLocaleDateString("en-US",{month:"short",day:"numeric"});
};
const lastNote = lead => {
  const ns = Array.isArray(lead&&lead.notes) ? lead.notes : [];
  return ns.length ? ns[ns.length-1] : null;
};
const daysInStage = lead => {
  const t = lead.stageEnteredAt || lead.createdAt;
  if(!t) return null;
  return Math.floor((Date.now() - new Date(t).getTime()) / 86400000);
};

// Remap data colors (stage/team) to theme-appropriate values for basic black/white schemes
// Stage colors are defined once on LEAD_STAGES; themes remap them so badges follow the scheme.
const NEO_RAMP = {
  "#0033A0":"#0E7FA6", "#3a5fc0":"#2A6B86", "#1a47b0":"#0B5C7A", "#4d7fd6":"#1E7E9E",
  "#00237a":"#0A5570", "#152b7a":"#12485E", "#0a6b34":"#0F8A5F", "#b0862a":"#6E7A82",
  "#c0504d":"#C0564F", "#787e88":"#5A6570", "#6b7280":"#55606B",
};
const MODERN_RAMP = {
  "#0033A0":"#0B1B2B", "#3a5fc0":"#1C3247", "#1a47b0":"#12617F", "#4d7fd6":"#0E9BC9",
  "#00237a":"#0B1B2B", "#152b7a":"#134C68", "#0a6b34":"#0F9D6B", "#b0862a":"#8A6A1E",
  "#c0504d":"#D6455C", "#787e88":"#66788A", "#6b7280":"#5B6B7C",
};
// Stage/assignee colors are fixed brand hexes (navy #0033A0 and friends). On a dark page
// they read as unreadable dark blue — Blake hit this on Pewter. Rather than hand-ramp every
// dark theme, lift any too-dark color until it clears the page it sits on.
const _hex2rgb = h => { const s=String(h||"").replace("#",""); if(s.length!==6) return null;
  return [0,2,4].map(i=>parseInt(s.slice(i,i+2),16)); };
const _lum = h => { const c=_hex2rgb(h); if(!c) return 1;
  const f=v=>{v/=255; return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4;};
  return 0.2126*f(c[0])+0.7152*f(c[1])+0.0722*f(c[2]); };
const _lift = (h, amt) => { const c=_hex2rgb(h); if(!c) return h;
  const m=c.map(v=>Math.round(v+(255-v)*amt));
  return "#"+m.map(v=>v.toString(16).padStart(2,"0")).join(""); };
const themeColor = (color, scheme, T) => {
  if(scheme==="black") return "#ffffff";
  if(scheme==="white") return "#000000";
  if(scheme==="neo")    return NEO_RAMP[String(color||"").toLowerCase()]    || NEO_RAMP[color]    || color;
  if(scheme==="modern") return MODERN_RAMP[String(color||"").toLowerCase()] || MODERN_RAMP[color] || color;
  const sc = COLOR_SCHEMES[scheme];
  const page = sc && sc.light && sc.light.page;
  if(page && _lum(page) < 0.18){                    // dark-ground theme
    let out = String(color||"");
    for(let i=0;i<6 && out.startsWith("#") && _lum(out) < 0.30; i++) out = _lift(out, 0.28);
    return out;
  }
  return color;
};
const saveWorksheetPDF = async () => {
  const node = document.querySelector(".mc-print");
  if (!node) { if (window.__flashSync) window.__flashSync("⚠️ No worksheet open"); return; }
  const timeout = (ms) => new Promise((_,rej)=>setTimeout(()=>rej(new Error("timed out")), ms));
  let clone = null;
  try {
    const mod = await import("html2pdf.js");
    const html2pdf = mod.default || mod;
    clone = document.createElement("div");
    Object.assign(clone.style, { position:"fixed", inset:"0", zIndex:"9999", background:"#ffffff", overflow:"auto", padding:"10px 0" });
    const liveCtl = node.querySelectorAll("input,textarea,select");
    liveCtl.forEach((el,i)=>el.setAttribute("data-pdfi", String(i)));
    let inner = node.cloneNode(true);
    inner.querySelectorAll(".mc-noprint").forEach(el=>el.remove());
    inner.querySelectorAll(".mc-pdfhide").forEach(el=>el.remove());
    inner.querySelectorAll(".mc-pdfshow").forEach(el=>{ el.style.display="block"; });
    // form controls render clipped in PDFs — swap each for a plain text block with the live value
    const dstCtl = inner.querySelectorAll("input,textarea,select");
    dstCtl.forEach((el)=>{
      const s = liveCtl[parseInt(el.getAttribute("data-pdfi")||"-1")]; if(!s) return;
      const cs = getComputedStyle(s);
      const d = document.createElement("div");
      d.textContent = s.tagName==="SELECT" ? (s.options[s.selectedIndex]?.text||"") : (s.type==="checkbox" ? (s.checked?"☑":"☐") : (s.value||""));
      d.style.cssText = `font-size:${cs.fontSize};font-weight:${s.type==="checkbox"?"400":cs.fontWeight};font-family:${cs.fontFamily};color:${cs.color};text-align:${cs.textAlign};padding:${cs.padding};line-height:1.35;box-sizing:border-box;width:100%;white-space:pre-wrap;`;
      el.replaceWith(d);
    });
    // hide empty explanation boxes; drop income sections with no data at all
    inner.querySelectorAll(".mc-expl-box").forEach(box=>{ if(!box.textContent.trim()) box.remove(); });
    const srcSecs = node.querySelectorAll(".mc-w2sec");
    const dstSecs = inner.querySelectorAll(".mc-w2sec");
    dstSecs.forEach((sec,i)=>{
      const s = srcSecs[i]; if(!s) return;
      const hasData = Array.from(s.querySelectorAll("input")).some(x=>x.type!=="checkbox" && x.value && parseFloat(String(x.value).replace(/[^0-9.]/g,""))>0 && !/^\d{1,2}\/\d{1,2}/.test(x.value));
      const hasNote = Array.from(s.querySelectorAll(".mc-expl")).some(x=>x.value.trim());
      if(!hasData && !hasNote) sec.remove();
    });
    Object.assign(inner.style, { width:"680px", maxWidth:"680px", margin:"0 auto", maxHeight:"none", overflow:"visible", borderRadius:"0", boxShadow:"none" });
    clone.appendChild(inner);
    document.body.appendChild(clone);
    // TIGHTEN FIRST, SCALE SECOND. Blake's actual complaint is that the PDF is "spaced out" —
    // the sheet is laid out for a TOUCH SCREEN, where 44px tap targets and generous padding
    // are correct. On paper that is wasted space. Compressing the screen-only padding takes a
    // full four-section sheet from ~1520px to roughly 1100px, which then fits one page at a
    // readable scale instead of being crushed to 0.56 or spilling to a second sheet.
    inner.querySelectorAll(".mc-w2sec, .mc-expl-box").forEach(el=>{
      el.style.marginBottom = "6px";
    });
    inner.querySelectorAll("div").forEach(el=>{
      const cs = el.style;
      // Only touch generous padding — leave anything already tight alone.
      const pad = parseFloat(cs.padding) || 0;
      if (pad >= 10) cs.padding = Math.max(4, pad * 0.55) + "px";
      const pt = parseFloat(cs.paddingTop) || 0, pb = parseFloat(cs.paddingBottom) || 0;
      if (pt >= 10) cs.paddingTop = Math.max(3, pt * 0.55) + "px";
      if (pb >= 10) cs.paddingBottom = Math.max(3, pb * 0.55) + "px";
      const mt = parseFloat(cs.marginTop) || 0, mb = parseFloat(cs.marginBottom) || 0;
      if (mt >= 10) cs.marginTop = Math.max(3, mt * 0.55) + "px";
      if (mb >= 10) cs.marginBottom = Math.max(3, mb * 0.55) + "px";
      if ((parseFloat(cs.minHeight) || 0) > 0) cs.minHeight = "0";
    });

    // COMPRESS FIRST, SCALE SECOND. Blake's actual words were "it's spaced out" — the sheet
    // is laid out for a phone screen, with tap-target padding on every row. Shrinking that
    // padding for print recovers far more height than scaling does, and unlike scaling it
    // costs nothing in legibility: the TYPE stays full size, only the air between it goes.
    inner.querySelectorAll(".mc-w2sec").forEach(sec=>{ sec.style.marginBottom = "6px"; });
    inner.querySelectorAll("div").forEach(d=>{
      const cs = d.style;
      // row padding like "9px 11px" → "3px 8px"; only touch generous vertical padding
      const m = /^(\d+)px\s+(\d+)px$/.exec(cs.padding || "");
      if (m && parseInt(m[1]) >= 7) cs.padding = `${Math.max(2, Math.round(parseInt(m[1]) * 0.4))}px ${m[2]}px`;
      if (cs.marginBottom && parseInt(cs.marginBottom) >= 10) cs.marginBottom = "5px";
      if (cs.marginTop && parseInt(cs.marginTop) >= 10) cs.marginTop = "5px";
      if (cs.gap && parseInt(cs.gap) >= 8) cs.gap = "4px";
    });
    // the explanation boxes are the tallest single thing on a full sheet
    inner.querySelectorAll(".mc-expl-box").forEach(b=>{ b.style.padding = "4px 8px"; });

    // FIT ON ONE PAGE. The sheet is laid out at a fixed 680px wide and was never scaled, so
    // anything taller than a page broke across two — usually leaving a nearly empty second
    // sheet, which is what makes it read as "spaced out" to an underwriter. Measure the real
    // height and shrink the whole thing to fit. html2canvas still renders at 2x, so the type
    // is genuinely smaller rather than resampled and blurry.
    const PAGE_RATIO = 11 / 8.5;                        // letter, portrait
    const usableH = Math.floor(680 * PAGE_RATIO) - 24;  // 680px-wide page, minus the 7mm margins
    const realH = inner.scrollHeight || inner.offsetHeight || 0;
    if (realH > usableH) {
      // Floor at 0.62 — below that a 10px figure drops under 7px and stops being legible,
      // and a clean two-page PDF beats an unreadable one-page PDF.
      const k = Math.max(0.62, usableH / realH);
      inner.style.transformOrigin = "top center";
      inner.style.transform = `scale(${k})`;
      const shell = document.createElement("div");
      shell.style.cssText = `width:680px;height:${Math.ceil(realH * k)}px;margin:0 auto;overflow:hidden;background:#ffffff;`;
      inner.parentNode.replaceChild(shell, inner);
      shell.appendChild(inner);
      inner = shell;
    }
    await Promise.race([
      html2pdf().set({
        margin: 7,
        filename: `henderson-worksheet-${new Date().toISOString().slice(0,10)}.pdf`,
        image: { type: "jpeg", quality: 0.96 },
        html2canvas: { scale: 2, useCORS: true, backgroundColor: "#ffffff", scrollY: 0, windowWidth: 700 },
        jsPDF: { unit: "mm", format: "letter", orientation: "portrait" },
        pagebreak: { mode: ["avoid-all", "css"] }
      }).from(inner).save(),
      timeout(25000),
    ]);
    clone.remove();
    if (window.__flashSync) window.__flashSync("📄 PDF saved — check your Downloads");
  } catch (e) {
    if (clone) clone.remove();
    if (window.__flashSync) window.__flashSync("⚠️ PDF failed: " + String(e?.message||e).slice(0,60));
  }
}
// Blake 9/9: the income worksheet's PDF button was hitting "Failed to fetch dynamically
// imported module" — the html2pdf.js chunk saveWorksheetPDF() depends on. The worksheet
// now exports as a JPG instead, built by hand here rather than through the generic
// makeJpgFile helper, because the export needs a few things that helper doesn't do:
//   1. Drop a period row (or the Base Pay Rate row) only if it's genuinely EMPTY — no
//      total, no dates. A row with real numbers stays in even if it's unchecked (not
//      counted toward qualifying), because that's often the whole point: Blake's own
//      example is overtime that's declining and isn't being used to qualify, but he
//      still wants underwriting to see it existed — it's a compensating factor, not
//      nothing. An unchecked-but-populated row gets a small "Not used" label instead
//      of being hidden, so the distinction is visible rather than silently lost.
//   2. Drop a whole income section (Overtime, Bonus, etc.) entirely only once NO row
//      in it has any data at all and there's no note — a section with real numbers
//      stays even if none of its rows are checked, for the same reason as above.
//   3. Drop an explanation box unless it actually has text in it.
// On top of that, this restyles it as a proper document (see the injected stylesheet
// below): the on-screen worksheet is a boxed, bordered card layout built for tapping,
// which reads as cramped once flattened into an image — the fix is an actual restyle
// into a plain exhibit (thin section rules, no per-cell grid lines), not just re-scaling.
const saveIncomeWorksheetJPG = async () => {
  const node = document.querySelector(".mc-print");
  if (!node) { if (window.__flashSync) window.__flashSync("⚠️ No worksheet open"); return; }
  let holder = null;
  try {
    if (window.__flashSync) window.__flashSync("Building image…");
    let h2c = null;
    try { const m = await import("html2canvas"); h2c = m.default || m; } catch {}
    if (!h2c) throw new Error("image engine unavailable");

    const w = Math.max(560, Math.round(node.offsetWidth || node.scrollWidth || 680));
    holder = document.createElement("div");
    holder.style.cssText = `position:fixed;left:-10000px;top:0;width:${w}px;background:#ffffff;`;
    const inner = node.cloneNode(true);
    flattenForExport(inner);   // strips .mc-noprint/buttons/checkboxes, swaps inputs for live-value spans

    // 1. Truly empty rows out; populated-but-unchecked rows stay and get labeled.
    inner.querySelectorAll(".mc-w2row[data-has='0']").forEach(r=>r.remove());
    inner.querySelectorAll(".mc-w2row[data-sel='0'][data-has='1']").forEach(r=>{
      r.style.opacity = "0.62";
      const tag = document.createElement("div");
      tag.textContent = "Not used";
      tag.style.cssText = "position:absolute;top:2px;right:4px;font-size:7.5px;font-weight:800;letter-spacing:0.05em;text-transform:uppercase;color:#9A6400;background:#FBF0D9;padding:1px 5px;border-radius:6px;";
      r.style.position = "relative";
      r.appendChild(tag);
    });
    // 3. Empty explanation boxes out (checked after flatten, so textContent holds the live value).
    inner.querySelectorAll(".mc-expl-box").forEach(box=>{ if(!box.textContent.trim()) box.remove(); });
    // 2. Sections with nothing left to show — no data in any row, no note — out entirely.
    inner.querySelectorAll(".mc-w2sec").forEach(sec=>{
      const hasRow = !!sec.querySelector(".mc-w2row");
      const hasNote = !!sec.querySelector(".mc-expl-box");
      if (!hasRow && !hasNote) sec.remove();
    });

    Object.assign(inner.style, { width:"680px", maxWidth:"680px", margin:"0 auto", maxHeight:"none", overflow:"visible", borderRadius:"0", boxShadow:"none" });
    inner.classList.add("mc-jpgexport");
    holder.appendChild(inner);
    document.body.appendChild(holder);

    // Blake 9/9: the actual "clean this up" redesign, not just re-scaling — the on-screen
    // worksheet is a boxed, bordered touch UI (built for tapping), which is why it read as
    // cramped once flattened into a document. This restyles it into a plain eFolder exhibit:
    // sections separated by a thin rule instead of individual cards, no per-cell grid lines,
    // a quieter icon badge, breathing room between rows instead of compressed padding.
    // Scoped to .mc-jpgexport (added to `inner` above) so none of this touches the live UI —
    // a bare <style> tag is global, and this DOM is a detached clone, but the CSS itself isn't.
    const style = document.createElement("style");
    style.textContent = `
      .mc-jpgexport{background:#ffffff!important;}
      .mc-jpgexport .mc-w2sec{border:none!important;box-shadow:none!important;border-radius:0!important;
        background:#ffffff!important;border-top:1px solid #E4E9F0!important;padding-top:16px!important;margin-bottom:2px!important;}
      .mc-jpgexport .mc-w2sec:first-of-type{border-top:none!important;padding-top:0!important;}
      .mc-jpgexport .mc-w2hdr{background:#ffffff!important;border-bottom:none!important;padding:0 0 10px!important;}
      .mc-jpgexport .mc-w2icon{width:18px!important;height:18px!important;font-size:9.5px!important;}
      .mc-jpgexport .mc-w2colhead{background:#ffffff!important;border-bottom:1px solid #E4E9F0!important;}
      .mc-jpgexport .mc-w2colhead>div{border-right:none!important;background:#ffffff!important;padding:4px 6px!important;}
      .mc-jpgexport .mc-w2row{border-bottom:1px solid #EEF1F5!important;background:#ffffff!important;}
      .mc-jpgexport .mc-w2row>div{border-right:none!important;background:#ffffff!important;padding:7px 6px!important;}
      .mc-jpgexport .mc-w2qual{background:#ffffff!important;border-bottom:none!important;
        border-top:1px solid #E4E9F0!important;padding:9px 6px!important;}
      .mc-jpgexport .mc-expl-box{background:#ffffff!important;padding:2px 6px 12px!important;}
    `;
    holder.appendChild(style);

    const canvas = await h2c(inner, { scale: 2, useCORS: true, backgroundColor: "#ffffff", windowWidth: w });
    const blob = await new Promise(res=>canvas.toBlob(res, "image/jpeg", 0.92));
    const file = new File([blob], `henderson-income-worksheet-${new Date().toISOString().slice(0,10)}.jpg`, { type: "image/jpeg" });
    await deliverFile(file, file.name);
  } catch (e) {
    if (window.__flashSync) window.__flashSync("⚠️ JPG failed: " + String(e?.message||e).slice(0,60));
  } finally {
    if (holder) holder.remove();
  }
};
function splitCSZ(cityStr, st, zp){
  const city0=String(cityStr||"").trim(), s0=String(st||"").trim().toUpperCase(), z0=String(zp||"").trim();
  if(s0||z0||!city0) return {city:city0, state:s0, zip:z0};
  let m=/^(.*?)[,\s]+([A-Za-z]{2})\.?(?:[,\s]+(\d{5}(?:-\d{4})?))?$/.exec(city0);
  if(m) return {city:m[1].replace(/,+$/,"").trim(), state:m[2].toUpperCase(), zip:m[3]||""};
  m=/^(.*?)[,\s]+(\d{5}(?:-\d{4})?)$/.exec(city0);
  if(m) return {city:m[1].replace(/,+$/,"").trim(), state:"", zip:m[2]};
  return {city:city0, state:"", zip:""};
}
function cszStr(rec){
  const p=splitCSZ(rec?.city, rec?.state, rec?.zip);
  return [p.city, [p.state, p.zip].filter(Boolean).join(" ")].filter(Boolean).join(", ");
}
// Street + city/state/zip on one line. Returns "" when there is nothing to show, so
// the caller can print a dash rather than a stray comma.
function fullAddr(rec){
  const street = String(rec?.address||"").trim();
  const csz    = cszStr(rec);
  return [street, csz].filter(Boolean).join(", ");
}
const nowStr    = () => { const d=new Date(); return `${d.toLocaleDateString("en-US",{month:"numeric",day:"numeric",year:"2-digit",timeZone:"America/New_York"})} · ${d.toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit",timeZone:"America/New_York"})}`; };
const inMonth   = (ds,m,y) => { if(!ds) return false; const d=dayOf(ds); return d.getMonth()===m&&d.getFullYear()===y; };
const fmtDate   = ds => { if(!ds) return "Not set"; const d=new Date(ds+"T12:00:00"); const m=d.getMonth()+1,day=d.getDate(),y=String(d.getFullYear()).slice(-2); return `${m}/${day}/${y}`; };
const fmtName   = name => { if(!name) return ""; const parts=name.split(","); if(parts.length>=2) return `${parts[1].trim()} ${parts[0].trim()}`; return name; };

// ─── CELEBRATION: Confetti + chime ────────────────────────────────────────────
function playClosingChime() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if(!AudioCtx) return;
    const ctx = new AudioCtx();
    // Pleasant ascending arpeggio (C-E-G-C major)
    const notes = [523.25, 659.25, 783.99, 1046.50];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.value = freq;
      osc.connect(gain); gain.connect(ctx.destination);
      const start = ctx.currentTime + i*0.11;
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(0.18, start+0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, start+0.5);
      osc.start(start); osc.stop(start+0.5);
    });
  } catch(e){}
}

function Confetti({onDone}) {
  const colors = ["#1a47b0","#0033A0","#787e88","#a3b18a","#8a6838","#bc6c5c","#c9954a","#7a8c5a"];
  const pieces = Array.from({length:90}).map((_,i)=>({
    id:i,
    left:Math.random()*100,
    delay:Math.random()*0.4,
    duration:2.2+Math.random()*1.5,
    color:colors[i%colors.length],
    size:6+Math.random()*7,
    rot:Math.random()*360,
    drift:(Math.random()-0.5)*180,
    shape:Math.random()>0.5?"50%":"2px",
  }));
  useEffect(()=>{ const t=setTimeout(onDone, 4000); return ()=>clearTimeout(t); },[onDone]);
  return (
    <div style={{position:"fixed",inset:0,zIndex:1000,pointerEvents:"none",overflow:"hidden"}}>
      <style>{`@keyframes confettiFall{0%{transform:translateY(-20px) translateX(0) rotate(0deg);opacity:1}100%{transform:translateY(105vh) translateX(var(--drift)) rotate(var(--rot));opacity:0.3}}`}</style>
      {pieces.map(p=>(
        <div key={p.id} style={{position:"absolute",top:0,left:`${p.left}%`,width:p.size,height:p.size,background:p.color,borderRadius:p.shape,"--drift":`${p.drift}px`,"--rot":`${p.rot+720}deg`,animation:`confettiFall ${p.duration}s ease-in ${p.delay}s forwards`}}/>
      ))}
    </div>
  );
}

