// Browser dictation. No server, no upload — the phone transcribes on-device and we just
// take the text. Returns null when the browser has no support, so the button can hide.
function makeDictation(onText, onEnd){
  const Ctor = typeof window!=="undefined" && (window.SpeechRecognition || window.webkitSpeechRecognition);
  if(!Ctor) return null;
  const r = new Ctor();
  r.continuous = true; r.interimResults = true; r.lang = "en-US";
  let settled = "";
  r.onresult = (e) => {
    let interim = "";
    for(let i=e.resultIndex; i<e.results.length; i++){
      const t = e.results[i][0].transcript;
      if(e.results[i].isFinal) settled += (settled && !/\s$/.test(settled) ? " " : "") + t.trim();
      else interim += t;
    }
    onText((settled + (interim ? " " + interim.trim() : "")).trim());
  };
  r.onerror = () => { onEnd && onEnd(); };
  r.onend   = () => { onEnd && onEnd(); };
  return r;
}
