function StageMoveGrid({T, lead, STAGE_MOVES, doMoveStage}) {
  const [firing,setFiring] = useState(null);
  const [err,setErr] = useState("");
  const fire = (t) => {
    if (firing) return;
    setFiring(t.id);
    setTimeout(()=>{
      try { doMoveStage(t); }
      catch(e){ setErr(String(e?.message||e)); setFiring(null); }
    }, 30);
  };
  return (
    <div style={{position:"relative",zIndex:20}}>
      <div className="lj-stagegrid" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6}}>
        {STAGE_MOVES.filter(t=>t.newStage!==lead.stage).map(t=>(
          <button key={t.id} type="button"
            onMouseDown={e=>{e.preventDefault();fire(t);}}
            onTouchEnd={e=>{e.preventDefault();fire(t);}}
            onClick={()=>fire(t)}
            style={{padding:"9px 6px",borderRadius:8,fontSize:11.5,fontWeight:800,cursor:"pointer",background:firing===t.id?"#0a6b34":(t.id==="onhold"?"transparent":T.navy),border:t.id==="onhold"&&firing!==t.id?`1.5px solid ${T.border}`:"none",color:t.id==="onhold"&&firing!==t.id?T.muted:"#fff",touchAction:"manipulation",WebkitTapHighlightColor:"rgba(255,255,255,0.2)"}}>
            {firing===t.id ? "⏳ Moving…" : `→ ${t.label}`}
          </button>
        ))}
      </div>
      {err&&<div style={{marginTop:7,background:"rgba(216,31,42,0.12)",border:"1px solid #d81f2a66",borderRadius:8,padding:"7px 10px",fontSize:10.5,color:"#d81f2a",fontWeight:700}}>Move failed: {err}</div>}
    </div>
  );
}

