  const lockDaysLeft = () => lockExpiry ? String(Math.max(0,Math.round((new Date(lockExpiry+"T12:00")-new Date().setHours(12,0,0,0))/86400000))) : "";
  const commitLockDays = (v) => { const d=parseInt(v); setLockDaysRaw(null); if(isNaN(d)) return; const dt=new Date(); dt.setDate(dt.getDate()+d); setLockExpiry(localISO(dt)); };
