  const [assignee,setAssignee]   = useState(lead.assignee);
  const [otherNote,setOtherNote] = useState(lead.otherNote||"");
  const [bTodos,setBTodos] = useState(Array.isArray(lead.borrowerTodos)?lead.borrowerTodos:[]);
  const [bNew,setBNew] = useState("");
  const [bPrev,setBPrev] = useState(false);
  const [contingency,setContingency] = useState(!!lead.homeSaleContingency);
  // Appraisal waiver: a file attribute, not a milestone. When on, the two appraisal
  // milestone rows are shown greyed as N/A rather than hidden — the file still has to
  // explain why nothing is stamped there.
  const [apprWaiver,setApprWaiver] = useState(!!lead.appraisalWaiver);
  const [ltab,setLtab] = useState(initialTab||"client");
  const [leadOpen,setLeadOpen] = useState(true);
