function bnplLine(fd){
  const n = Math.max(0, parseInt(fd.transactions)||0);
  const tot = Number(fd.total)||0;
  const dates = fd.first_date ? ` ${fd.first_date}${fd.last_date&&fd.last_date!==fd.first_date?`–${fd.last_date}`:""}` : "";
  return `${fd.provider||"Unknown"}${fd.type&&fd.type!=="BNPL"?` (${fd.type})`:" BNPL"} — ${n} debit${n===1?"":"s"}${dates}${tot>0?` totaling $${tot.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`:""}${fd.recurring?" · recurring":""}`;
}
// ── AI CORRECTIONS ────────────────────────────────────────────────────────────
// Not model training — a memory of what Blake fixed. Each correction is replayed into the
// next prompt as a worked example, so the same mistake stops recurring. Kept small and
// scoped per scanner so one tool's lessons never bleed into another's.
const AI_LEARN_KEY = "lj_ai_corrections_v1";
function loadCorrections(kind){
  try{ const all=JSON.parse(localStorage.getItem(AI_LEARN_KEY)||"{}"); return Array.isArray(all[kind])?all[kind]:[]; }catch(e){ return []; }
}
function saveCorrection(kind, note){
  const t=String(note||"").trim(); if(!t) return [];
  try{
    const all=JSON.parse(localStorage.getItem(AI_LEARN_KEY)||"{}");
    const list=Array.isArray(all[kind])?all[kind]:[];
    if(list.some(x=>String(x.note).toLowerCase()===t.toLowerCase())) return list;   // no duplicates
    const next=[...list,{note:t,on:new Date().toISOString().slice(0,10)}].slice(-12); // keep the last 12
    all[kind]=next; localStorage.setItem(AI_LEARN_KEY, JSON.stringify(all));
    return next;
  }catch(e){ return loadCorrections(kind); }
}
function forgetCorrection(kind, idx){
  try{
    const all=JSON.parse(localStorage.getItem(AI_LEARN_KEY)||"{}");
    const list=Array.isArray(all[kind])?all[kind]:[];
    all[kind]=list.filter((_,i)=>i!==idx);
    localStorage.setItem(AI_LEARN_KEY, JSON.stringify(all));
    return all[kind];
  }catch(e){ return loadCorrections(kind); }
}
// Appended to the system prompt so the model sees past corrections before it reads anything.
function correctionsPrompt(kind){
  const list=loadCorrections(kind);
  if(!list.length) return "";
  return "\n\nCORRECTIONS FROM PREVIOUS RUNS — the loan officer fixed these before. Apply them:\n"
    + list.map((c,i)=>`${i+1}. ${c.note}`).join("\n");
}
function parseBankScan(raw){
  try{
    let t = String(raw||"").replace(/```json|```/g,"").trim();
    const a=t.indexOf("{"), b=t.lastIndexOf("}");
    if(a<0||b<a) return { ok:false, findings:[], none:false, notes:"", stmt:{} };
    const j = JSON.parse(t.slice(a,b+1));
    const num = v => { const n=Number(String(v??"").replace(/[^0-9.\-]/g,"")); return Number.isFinite(n)?n:0; };
    const list = Array.isArray(j.findings) ? j.findings : [];
    const findings = list.map(fd=>({
      provider: String(fd?.provider||"Unknown").slice(0,40),
      // BNPL · OVERDRAFT · LOAN_PAYOFF · LOAN_PAYMENT · LARGE_DEPOSIT · NSF
      type: String(fd?.type||"BNPL").toUpperCase().replace(/[^A-Z_]/g,"").slice(0,14) || "BNPL",
      transactions: Math.max(0, parseInt(fd?.transactions)||0),
      total: num(fd?.total),
      first_date: String(fd?.first_date||"").slice(0,12),
      last_date: String(fd?.last_date||"").slice(0,12),
      samples: (Array.isArray(fd?.samples)?fd.samples:[]).slice(0,4).map(x2=>String(x2).slice(0,90)),
      pages: (Array.isArray(fd?.pages)?fd.pages:[]).map(x=>parseInt(x)||0).filter(Boolean).slice(0,8),
      recurring: !!fd?.recurring,
      concern: String(fd?.concern||"").slice(0,220),
    }));
    // sort so the things underwriting cares about most are first
    const RANK = { OVERDRAFT:0, NSF:0, BNPL:1, LOAN_PAYOFF:2, LOAN_PAYMENT:3, LARGE_DEPOSIT:4 };
    findings.sort((x,y)=>(RANK[x.type]??9)-(RANK[y.type]??9) || y.total-x.total);
    return { ok:true, findings, none: findings.length===0,
      notes:String(j?.notes||"").slice(0,900),
      synopsis:String(j?.synopsis||"").slice(0,1400),
      stmt:(j?.statement&&typeof j.statement==="object")?j.statement:{} };
  } catch { return { ok:false, findings:[], none:false, notes:"", stmt:{} }; }
}
