  const KIND={"pa-letter":"Pre-Approval Letter","cover":"Cover Letter","opscover":"Operations Cover Letter","compare":"Shopping Comparison","contract":"Purchase Contract","offer":"Numbers Sheet","doc":"Document","w2sheet":"W2 Income Worksheet","saesheet":"Self Employed Worksheet","bankreview":"Bank Statement Review","scenario":"Calculator Result","closepkg":"Closing Package"};
  const lb={fontSize:9.5,fontWeight:800,color:T.muted,letterSpacing:"0.09em",textTransform:"uppercase",marginBottom:6};
