  const loadNaf = async () => {
    try{
      const sb = await getSupabase(); if(!sb) return;
      const { data, error } = await sb.from("naf_leads").select("*")
        .order("started_at", { ascending:false })
        .limit(60);
      if(error || !Array.isArray(data)) return;
      setNafLeads(data);
      // Only Blake's session creates files, and only once per application.
      if(currentUser!==BOSS || nafBusy.current) return;
      nafBusy.current = true;
      try{
        // RECONCILE, don't just claim. A row is only "done" when a real file exists for it.
        // The old loop flipped claimed=true BEFORE creating the file, so any failure or refresh
        // in between orphaned that application permanently — Blake 8/3: "no created file",
        // new loans missing until several refreshes. The claim is now a lock we release on failure.
        // Match on app number when we have it, and fall back to phone/email/name so the
        // reconcile still can't double-create before clients.naf_app exists in the database.
        const dig = s => String(s||"").replace(/[^0-9]/g,"").slice(-10);
        const low = s => String(s||"").trim().toLowerCase();
        const all = [...leadsRef.current, ...loansRef.current];
        const haveApp   = new Set(all.map(l=>l.nafApp).filter(Boolean));
        const havePhone = new Set(all.map(l=>dig(l.phone)).filter(x=>x.length===10));
        const haveEmail = new Set(all.map(l=>low(l.email)).filter(Boolean));
        const haveName  = new Set(all.filter(l=>l.stage==="new").map(l=>low(l.name||l.borrower)).filter(Boolean));
        const known = n2 => haveApp.has(n2.app_number)
          || (dig(n2.borrower_phone).length===10 && havePhone.has(dig(n2.borrower_phone)))
          || (low(n2.borrower_email) && haveEmail.has(low(n2.borrower_email)))
          || (low(n2.borrower_name)  && haveName.has(low(n2.borrower_name)));
        for(const n of data){
          if(known(n)){
            // Already have a file. If the borrower has since FINISHED the application and the
            // file is still sitting untouched in W for App, promote it into the New Loan
            // review queue and flag it priority.
            if(n.status==="complete"){
              const rec = all.find(l=>l.nafApp===n.app_number
                || (dig(l.phone).length===10 && dig(l.phone)===dig(n.borrower_phone))
                || (low(l.email) && low(l.email)===low(n.borrower_email)));
              if(rec && rec.stage==="new" && rec.newStatus==="W for App"){
                saveLead({...rec, newStatus:"New Loans", priority:true,
                  notes:[...(Array.isArray(rec.notes)?rec.notes:[]),
                         {author:"NAF Hub", time:nowStr(), text:`Application completed \u00b7 ${n.app_number}`}]});
              }
            }
            continue;
          }
          if(n.claimed){ nafToLead(n); continue; }      // claimed but orphaned — heal it
          const { data: won } = await sb.from("naf_leads")
            .update({ claimed:true, claimed_at:new Date().toISOString() })
            .eq("app_number", n.app_number).eq("claimed", false).select();
          if(!won || !won.length) continue;             // another device got it
          try { nafToLead(n); }
          catch(e){ await sb.from("naf_leads").update({ claimed:false }).eq("app_number", n.app_number); }
        }
      } finally { nafBusy.current = false; }
    }catch(e){ warnWrite("NAF lead")(e); }
  };
  // Every NAF application becomes a New Loans file, flagged priority.
  const nafToLead = (n) => {
    const nm = String(n.borrower_name||"").trim() || String(n.borrower_email||"").split("@")[0] || n.app_number;
    const csz = splitCSZ(n.city||"", n.state||"", n.zip||"");
    const money = v => Number(String(v||"").replace(/[^0-9.]/g,""))||0;
    const lead = {
      id: uid(), name: nm, borrower: nm, phone: n.borrower_phone||"", email: n.borrower_email||"",
      stage:"new", priority: n.status==="complete",   // unfinished apps sit quietly in W for App
      newStatus: nafAutoStatus(n),
      loanPurpose: n.purpose || "Purchase", loanType: n.loan_type || LOAN_TYPE_TBD,
      loanAmount: money(n.loan_amount), amount: money(n.loan_amount),
      purchasePrice: money(n.purchase_price),
      address: n.address||"", city: csz.city, state: csz.state, zip: csz.zip,
      realtorAgent: agentSrc(n.agent), titleCompany:"", processor:DEFAULT_PROCESSOR, servicer:"",
      rate:null, rateLocked:false, lockExpiry:"", closingDate:"",
      milestones:{}, checklist:{}, borrowerTodos:[], notesCount:0,
      source:"NAF Hub", assignee: BOSS, nafApp: n.app_number,
      notes:[{author:"NAF Hub", time:nowStr(),
        text:`Application ${n.status==="complete"?"completed":"started"} \u00b7 ${n.app_path||"application"} \u00b7 ${n.app_number}`
          + [n.borrower_email?`\nEmail: ${n.borrower_email}`:"",
             n.borrower_phone?`\nPhone: ${n.borrower_phone}`:"",
             money(n.loan_amount)?`\nLoan amount: $${money(n.loan_amount).toLocaleString()}`:"",
             n.address?`\nProperty: ${[n.address,[csz.city,csz.state,csz.zip].filter(Boolean).join(" ")].filter(Boolean).join(", ")}`:""].join("")}],
      createdAt: n.started_at || new Date().toISOString(),
    };
    addLead(lead);
    return lead;
  };
